class ToolTip:
    """Owner-scoped, bounded hover help; never survives a stale hover/focus."""

    poll_ms = 100
    lifetime_ms = 8000

    def __init__(self, widget, text, delay=5000, *, bind_hover=True):
        self.widget, self.text, self.delay = widget, text, delay
        self.job = self.popup = None
        self.watch_job = self.expire_job = None
        self.owner = widget.winfo_toplevel()
        while isinstance(self.owner, tk.Menu):
            self.owner = self.owner.master.winfo_toplevel()
        self.owner_bindings = []
        if bind_hover:
            widget.bind("<Enter>", self._enter, add="+")
        widget.bind("<Leave>", self.hide, add="+")
        widget.bind("<Button>", self.hide, add="+")
        widget.bind("<MouseWheel>", self.hide, add="+")
        widget.bind("<Unmap>", self.hide, add="+")
        widget.bind("<Destroy>", self.hide, add="+")

    def _enter(self, _event=None):
        self.hide()
        self._schedule()

    def _schedule(self):
        if not self._eligible():
            return
        # Bind only for the lifetime of a pending/visible tooltip. No root-wide
        # permanent callbacks accumulating as preview tabs/menus are destroyed.
        for sequence in ("<FocusOut>", "<KeyPress>", "<ButtonPress>", "<Unmap>"):
            token = self.owner.bind(sequence, self.hide, add="+")
            self.owner_bindings.append((sequence, token))
        self.job = self.widget.after(self.delay, self.show)
        self.watch_job = self.widget.after(self.poll_ms, self._watch)

    def _eligible(self):
        try:
            if not self.widget.winfo_viewable() or not self.owner.winfo_viewable():
                return False
            focus = self.owner.focus_displayof()
            if focus is None or focus.winfo_toplevel() != self.owner:
                return False
            x, y = self.widget.winfo_pointerxy()
            return self._target_at(x, y)
        except (tk.TclError, KeyError):
            return False

    def _target_at(self, x, y):
        target = self.widget.winfo_containing(x, y)
        return target == self.widget

    def _watch(self):
        self.watch_job = None
        if not self._eligible():
            self.hide()
        else:
            self.watch_job = self.widget.after(self.poll_ms, self._watch)

    def show(self):
        self.job = None
        if not self._eligible():
            self.hide()
            return
        text = self.text() if callable(self.text) else self.text
        if not text:
            self.hide()
            return
        if self.popup is not None:
            return
        self.popup = tk.Toplevel(self.owner, takefocus=False)
        self.popup.withdraw()
        self.popup.overrideredirect(True)
        # Owned help must not float globally above unrelated applications.
        self.popup.transient(self.owner)
        x, y = self.widget.winfo_pointerxy()
        self.popup.geometry(f"+{x + 14}+{y + 18}")
        palette = getattr(self.owner, "palette", {})
        tk.Label(self.popup, text=text, justify="left", wraplength=900,
                 background=palette.get("tooltip", "#fffbd6"),
                 foreground=palette.get("tooltip_text", "#18232c"),
                 relief="solid", borderwidth=1, padx=7, pady=4).pack()
        # If the pointer approaches the help window, dismiss it before a click
        # can be intercepted. Escape and owner input also dismiss immediately.
        self.popup.bind("<Enter>", self.hide, add="+")
        self.popup.bind("<ButtonPress>", self.hide, add="+")
        self.popup.deiconify()
        self.expire_job = self.widget.after(self.lifetime_ms, self.hide)

    def hide(self, _event=None):
        for name in ("job", "watch_job", "expire_job"):
            token = getattr(self, name)
            if token is not None:
                try: self.widget.after_cancel(token)
                except tk.TclError: pass
                setattr(self, name, None)
        for sequence, token in self.owner_bindings:
            try: self.owner.unbind(sequence, token)
            except tk.TclError: pass
        self.owner_bindings.clear()
        if self.popup is not None:
            try: self.popup.destroy()
            except tk.TclError: pass
            self.popup = None


class TreeItemToolTip(ToolTip):
    """Shows delayed text for the Treeview row currently under the pointer."""

    def __init__(self, tree, text_for_item, delay=3000):
        self.tree, self.text_for_item, self.delay = tree, text_for_item, delay
        self.item = ""
        super().__init__(tree, self._text, delay, bind_hover=False)
        tree.bind("<Motion>", self._motion, add="+")

    def _text(self):
        return self.text_for_item(self.item) if self.item else ""

    def _target_at(self, x, y):
        return (super()._target_at(x, y) and bool(self.item)
                and self.tree.identify_row(y - self.tree.winfo_rooty()) == self.item)

    def _motion(self, event):
        item = self.tree.identify_row(event.y)
        if item == self.item:
            return
        self.hide(); self.item = item
        if item and self.text_for_item(item):
            self._schedule()

    def hide(self, _event=None):
        super().hide(_event)
        self.item = ""


class MenuToolTip(ToolTip):
    def __init__(self, menu, descriptions, delay=5000):
        self.menu, self.descriptions, self.delay = menu, descriptions, delay
        self.last_index = None
        super().__init__(menu, self._text, delay, bind_hover=False)
        menu.bind("<<MenuSelect>>", self._selected, add="+")

    def _selected(self, _event=None):
        try: index = self.menu.index("active")
        except tk.TclError: index = None
        if index == self.last_index: return
        self.hide(); self.last_index = index
        if index is not None and self.menu.type(index) != "separator":
            self._schedule()

    def _text(self):
        try: label = self.menu.entrycget(self.last_index, "label")
        except tk.TclError: return ""
        return self.descriptions.get(label, label.replace("\t", " — "))

    def _target_at(self, x, y):
        return (super()._target_at(x, y) and self.last_index is not None
                and self.menu.index("active") == self.last_index)

    def hide(self, _event=None):
        super().hide(_event)
        self.last_index = None


def install_button_tooltips(root) -> None:
    for widget in root.winfo_children():
        if isinstance(widget, (ttk.Button, tk.Button, tk.Menubutton)) and not hasattr(widget, "_pfc_tooltip"):
            text = str(widget.cget("text"))
            widget._pfc_tooltip = ToolTip(widget, BUTTON_HELP.get(text, f"Activate {text}."))
        install_button_tooltips(widget)


# Source: pycommander/columnsettings.py
"""Display-only column settings; sorting always uses underlying metadata."""
from datetime import datetime


def modified_text(timestamp, date_order="ymd", time_style="24"):
    value = datetime.fromtimestamp(timestamp)
    date = value.strftime("%m/%d/%Y" if date_order == "mdy" else "%Y/%m/%d")
    if time_style == "none":
        return date
    clock = (f"{value.hour % 12 or 12:02}{value.minute:02}{'a' if value.hour < 12 else 'p'}"
             if time_style == "12" else value.strftime("%H:%M"))
    return date + " " + clock


def font_snapshot(font, **changes):
    """Preserve negative pixel sizes: Font.actual() converts them to points."""
    attributes = font.actual()
    attributes['size'] = font.cget('size')
    attributes.update(changes)
    return attributes


# Source: pycommander/pathbar.py
"""Single-line logical breadcrumbs with an explicit full-path editor."""


import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk






def path_ancestors(path):
    """Keep real targets, including drive/UNC roots, separate from labels."""
    return [(p.name or str(p), p) for p in [*reversed(path.parents), path]]


def fit_crumbs(parts, width, measure):
    """Return (label, original index, pixel width); None denotes overflow."""
    if not parts or width <= 0:
        return []
    widths = [measure(label) + 20 for label, _ in parts]
    start = 0
    overflow = measure("…") + 20
    while start < len(parts) - 1 and sum(widths[start:]) + (overflow if start else 0) > width:
        start += 1
    # In very narrow panes the current directory takes precedence over overflow.
    show_overflow = start > 0 and width >= overflow + measure("MMMM") + 20
    remaining = max(1, width - (overflow if show_overflow else 0))
    result = [("…", None, overflow)] if show_overflow else []
    for index in range(start, len(parts)):
        label = parts[index][0]
        space = min(widths[index], remaining)
        if measure(label) > max(0, space - 20):
            length = len(label)
            while length > 0:
                candidate = label[:(length + 1) // 2] + "…" + (label[-(length // 2):] if length > 1 else "")
                if measure(candidate) <= max(0, space - 20):
                    break
                length -= 1
            label = candidate if length else "…"
        result.append((label, index, space))
        remaining -= space
    return result


class PathBar(ttk.Frame):
    def __init__(self, master, variable, parts, activate, submit, focus_files):
        super().__init__(master)
        self.variable, self.parts = variable, parts
        self.activate, self.submit, self.focus_files = activate, submit, focus_files
        self.editing = self.submitting = False
        self._closed = False
        self._redraw_job = None
        self._owner = self.winfo_toplevel()
        # Never mix a live system named font with a copied bold font. Windows
        # can refresh named fonts after unlock without resizing this Canvas.
        self.normal = tkfont.Font(root=self, font="TkDefaultFont")
        self.link = tkfont.Font(root=self, font="TkDefaultFont")
        self.bold = tkfont.Font(root=self, font="TkDefaultFont")
        self.committed = variable.get()
        self.columnconfigure(0, weight=1)
        self.canvas = tk.Canvas(self, width=1, highlightthickness=0, takefocus=1)
        self.canvas.grid(row=0, column=0, sticky="nsew")
        self.entry = ttk.Entry(self, textvariable=variable, width=1)
        self.edit_button = ttk.Button(self, text="✎", width=2, command=self.begin_edit)
        self.edit_button.grid(row=0, column=1, sticky="ns")
        self.tooltip = ToolTip(self.canvas, lambda: self.committed, delay=700)
        ToolTip(self.edit_button, lambda: tr("Edit path (Ctrl+L / F12)"), delay=700)
        for sequence in ("<Configure>", "<Expose>", "<Map>", "<Visibility>", "<<ThemeChanged>>"):
            self.canvas.bind(sequence, self.request_redraw)
        self._focus_binding = self._owner.bind("<FocusIn>", self.request_redraw, add="+")
        self.canvas.bind("<Button-1>", self._click)
        self.canvas.bind("<Return>", self.begin_edit)
        self.canvas.bind("<space>", self.begin_edit)
        self.entry.bind("<Return>", self._submit)
        self.entry.bind("<Escape>", self.cancel)
        self.entry.bind("<FocusOut>", self._focus_out)
        self._trace = variable.trace_add("write", self._changed)
        self.bind("<Destroy>", self._destroy, add="+")
        self._regions = []
        self._overflow_menu = None
        self.redraw()

    def _destroy(self, event):
        if event.widget is self:
            self._closed = True
            if self._redraw_job is not None:
                self.after_cancel(self._redraw_job)
                self._redraw_job = None
            self._owner.unbind("<FocusIn>", self._focus_binding)
            self.variable.trace_remove("write", self._trace)
            self.tooltip.hide()

    def _changed(self, *_):
        if not self.editing:
            self.committed = self.variable.get()
            self.redraw()

    def set_location(self, text):
        """A real navigation supersedes an unsubmitted edit, even without blur."""
        self.editing = False
        self.committed = text
        self.entry.grid_remove()
        self.canvas.grid()
        self.variable.set(text)

    def begin_edit(self, _event=None):
        if not self.editing:
            self.variable.set(self.committed)
            self.editing = True
            self.canvas.grid_remove()
            self.entry.grid(row=0, column=0, sticky="nsew")
        self.entry.focus_set()
        self.entry.selection_range(0, "end")
        return "break"

    def cancel(self, _event=None, focus=True):
        if self.editing:
            self.editing = False
            self.variable.set(self.committed)
            self.entry.grid_remove()
            self.canvas.grid()
            if focus:
                self.focus_files()
        return "break"

    def _focus_out(self, _event=None):
        if not self.submitting:
            self.cancel(focus=False)

    def _submit(self, _event=None):
        raw = self.variable.get()
        self.submitting = True
        try:
            success = self.submit()
        finally:
            self.submitting = False
        if success:
            self.committed = self.variable.get()
            self.cancel(focus=False)
        else:
            self.begin_edit()
            self.variable.set(raw)
            self.entry.focus_set()
        return "break"

    def request_redraw(self, _event=None):
        if not self._closed and self._redraw_job is None:
            self._redraw_job = self.after_idle(self.redraw)

    def redraw(self, _event=None):
        if self._closed:
            return
        if self._redraw_job is not None:
            self.after_cancel(self._redraw_job)
            self._redraw_job = None
        palette = getattr(self.winfo_toplevel(), "palette", {})
        restore = getattr(self._owner, "_ensure_font_scale", None)
        if restore is not None:
            restore()
        font = tkfont.nametofont("TkDefaultFont")
        attributes = font_snapshot(font)
        self.normal.configure(**dict(attributes, underline=0))
        self.link.configure(**dict(attributes, underline=1))
        self.bold.configure(**dict(attributes, weight="bold", underline=1))
        bg, fg = palette.get("entry", "#ffffff"), palette.get("text", "#18232c")
        self.canvas.configure(background=bg, height=font.metrics("linespace") + 10)
        self.canvas.delete("all")
        parts = self.parts()
        if self.committed.startswith("["):
            parts = [(self.committed, None)]
        self._parts = parts
        self._regions = []
        x, height = 0, max(self.canvas.winfo_height(), font.metrics("linespace") + 10)
        for label, index, width in fit_crumbs(parts, self.canvas.winfo_width(), self.bold.measure):
            target = parts[index][1] if index is not None else None
            is_folder = target is not None and target.parent != target
            label_font = self.bold if index == len(parts) - 1 else self.link
            if not is_folder:
                label_font = self.normal
            self.canvas.create_text(x + 4, height / 2, text=label, anchor="w",
                                    fill=fg, font=label_font, tags=("folder" if is_folder else "root",))
            if index is not None and index < len(parts) - 1:
                self.canvas.create_text(x + width - 8, height / 2, text="›", fill=fg, font=self.normal)
            self._regions.append((x, x + width, index))
            x += width

    def _click(self, event):
        for left, right, index in self._regions:
            if left <= event.x < right:
                if index is None:
                    if self._overflow_menu is not None:
                        self._overflow_menu.destroy()
                    menu = tk.Menu(self, tearoff=False, font="TkMenuFont")
                    self._overflow_menu = menu
                    palette = getattr(self.winfo_toplevel(), "palette", {})
                    if palette:
                        menu.configure(background=palette["menu"], foreground=palette["menu_text"],
                                       activebackground=palette["menu_active"], activeforeground=palette["menu_active_text"])
                    visible = [i for _, _, i in self._regions if i is not None]
                    for label, target in self._parts[:min(visible)]:
                        menu.add_command(label=label, command=lambda p=target: self.activate(p))
                    try:
                        menu.tk_popup(event.x_root, event.y_root)
                    finally:
                        menu.grab_release()
                elif self._parts[index][1] is not None:
                    self.activate(self._parts[index][1])
                return "break"


# Source: pycommander/homeprefix.py
"""Local-only common-folder discovery, preferences, matching and small icons."""


import json
import configparser
import os
from pathlib import Path
import tkinter as tk
import tkinter.font as tkfont
from functools import lru_cache
import math
from tkinter import ttk, filedialog, messagebox




PREFIX_ICONS = {"home": "User folder", "cloud": "OneDrive", "download": "Downloads",
                "code": "Code", "documents": "Documents", "photos": "Photos"}
CUSTOM_ICONS = ("code", "documents", "photos")


def load_custom_prefixes(config):
    try:
        saved = json.loads(config.get("home_prefixes", "custom", fallback="[]"))
    except (ValueError, TypeError, configparser.Error):
        saved = []
    if not isinstance(saved, list):
        saved = []
    result = []
    for index, default in enumerate(CUSTOM_ICONS):
        item = saved[index] if index < len(saved) and isinstance(saved[index], dict) else {}
        icon = item.get("icon", default)
        path = item.get("path", "")
        result.append({"icon": icon if isinstance(icon, str) and icon in PREFIX_ICONS else default,
                       "path": path if isinstance(path, str) else ""})
    return result


def save_custom_prefixes(config, items):
    if not config.has_section("home_prefixes"):
        config.add_section("home_prefixes")
    # ConfigParser uses % interpolation; preserve literal percent in folder names.
    config.set("home_prefixes", "custom", json.dumps(items, ensure_ascii=False).replace("%", "%%"))


def discover_home_prefixes():
    home = Path.home()
    downloads = home / "Downloads"
    clouds = [os.environ.get(key, "") for key in ("OneDrive", "OneDriveConsumer", "OneDriveCommercial")]
    if os.name == "nt":
        import winreg
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                    r"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders") as key:
                value, _ = winreg.QueryValueEx(key, "{374DE290-123F-4565-9164-39C4925E467B}")
                downloads = Path(os.path.expandvars(value))
        except OSError:
            pass
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\OneDrive\Accounts") as accounts:
                for index in range(winreg.QueryInfoKey(accounts)[0]):
                    try:
                        with winreg.OpenKey(accounts, winreg.EnumKey(accounts, index)) as account:
                            clouds.append(winreg.QueryValueEx(account, "UserFolder")[0])
                    except OSError:
                        continue
        except OSError:
            pass
    elif (home / "OneDrive").is_dir():
        clouds.append(str(home / "OneDrive"))
    result = [(home, "home"), (downloads, "download")]
    for value in clouds:
        if isinstance(value, str) and value:
            path = Path(os.path.normpath(os.path.expandvars(value))).expanduser()
            if path.is_absolute() and (path, "cloud") not in result:
                result.append((path, "cloud"))
    return result


def match_home_prefix(path, automatic, custom):
    """Path-component match; deepest wins, a custom slot wins equal depth."""
    candidates = list(automatic)
    for item in reversed(custom):
        if item["path"]:
            # Use the same path flavour, also allowing pure Windows-path tests.
            prefix = type(path)(os.path.normpath(item["path"]))
            if prefix.is_absolute():
                candidates.append((prefix, item["icon"]))
    match = None
    for prefix, icon in candidates:
        try:
            path.relative_to(prefix)
        except ValueError:
            continue
        if match is None or len(prefix.parts) >= len(match[0].parts):
            match = (prefix, icon)
    return match


def prefix_icon_size(widget):
    """One physical-pixel size for toolbar, popup and preferences at any DPI."""
    return max(12, tkfont.nametofont("TkDefaultFont", root=widget).metrics("linespace"))


@lru_cache(maxsize=128)
def prefix_icon_png(kind, size, foreground="#34465a"):
    """Rasterize vector geometry at 4x, then alpha-aware downsample to native size."""
    supersample = 4
    extent = size * supersample
    pixels = bytearray(extent * extent * 4)
    unit = extent / 32
    # Distinct, saturated hues identify the hidden prefix at a glance. Root is
    # deliberately neutral and has a different silhouette from every prefix.
    colors = {"home": "#ef9000", "cloud": "#0085f5", "download": "#00a653",
              "code": "#8836ef", "documents": "#009fac", "photos": "#ed297e"}
    face = _hex_rgba(colors.get(kind, colors["home"]))
    white = (255, 255, 255, 255)
    def paint(bounds, inside, color):
        x1, y1, x2, y2 = bounds
        for y in range(max(0, math.floor(y1*unit)), min(extent, math.ceil(y2*unit))):
            py = (y+.5)/unit
            for x in range(max(0, math.floor(x1*unit)), min(extent, math.ceil(x2*unit))):
                px = (x+.5)/unit
                if inside(px, py):
                    index = (y*extent+x)*4
                    pixels[index:index+4] = bytes(color(px, py) if callable(color) else color)
    def rounded(x1, y1, x2, y2, radius, color):
        def inside(x, y):
            cx = max(x1+radius, min(x, x2-radius))
            cy = max(y1+radius, min(y, y2-radius))
            return (x-cx)**2 + (y-cy)**2 <= radius**2
        paint((x1,y1,x2,y2), inside, color)
    def circle(x, y, radius, color=white):
        paint((x-radius,y-radius,x+radius,y+radius), lambda px,py: (px-x)**2+(py-y)**2 <= radius**2, color)
    def line(x1,y1,x2,y2,width=1.8,color=white):
        r = width/2
        paint((min(x1,x2)-r,min(y1,y2)-r,max(x1,x2)+r,max(y1,y2)+r),
              lambda x,y: _distance_to_segment(x,y,x1,y1,x2,y2) <= r, color)
    if kind == "parent":
        ink = _hex_rgba(foreground)
        line(16,27,16,5,2.4,ink); line(7,14,16,5,2.4,ink); line(16,5,25,14,2.4,ink)
        return _rgba_png_downsample(pixels, size, supersample)
    if kind == "root":
        rounded(2,3,30,29,3,_hex_rgba("#52687e"))
        rounded(3,4,29,21,2,_hex_rgba("#71879c"))
        # A directory-tree badge on a drive, rather than the user-folder badge.
        rounded(13,7,19,11,1,white)
        line(16,11,16,14,1.4); line(9,14,23,14,1.4)
        for x in (9,23):
            line(x,14,x,16,1.4); rounded(x-3,16,x+3,19,1,white)
        line(7,25,20,25,1.6); circle(25,25,1.2)
        return _rgba_png_downsample(pixels, size, supersample)
    rear = tuple(round(c*.79) for c in face[:3]) + (255,)
    rounded(2,3,14,12,2,rear); rounded(2,6,30,29,2.5,rear)
    # A restrained highlight separates the front flap from the rear tab.
    def gradient(x,y):
        light = max(0, .19*(28-y)/19)
        return tuple(round(c+(255-c)*light) for c in face[:3])+(255,)
    rounded(2,9,30,29,2.5,gradient)
    line(5,10,27,10,.65,tuple(round(c+(255-c)*.28) for c in face[:3])+(255,))
    if kind == "home":
        circle(16,15,3.1); rounded(10,19.5,22,25.5,3,white)
    elif kind == "cloud":
        circle(11,21,3.3); circle(16,18.2,4.3); circle(21.5,21,3.1)
        rounded(10,20,23,24.1,1.7,white)
    elif kind == "download":
        line(16,13,16,22,2.1); line(12,18.5,16,22,2.1); line(20,18.5,16,22,2.1)
        line(10,25,22,25,1.8)
    elif kind == "code":
        line(11,14,7,19); line(7,19,11,24)
        line(21,14,25,19); line(25,19,21,24); line(18,13,14,25)
    elif kind == "documents":
        rounded(10,12,22,26,1.4,white)
        for y in (16,19,22): line(13,y,19,y,1.2,face)
    else:
        rounded(7,12,25,26,1.5,white); rounded(8.5,13.5,23.5,24.5,.5,face)
        circle(12,17,1.6); line(9.5,23,15,18.5,1.5); line(15,18.5,19,23,1.5)
        line(18,22,21,19.5,1.5); line(21,19.5,23,22,1.5)
    return _rgba_png_downsample(pixels, size, supersample)


def prefix_icon(master, kind, size=None, foreground="#34465a"):
    size = prefix_icon_size(master) if size is None else size
    return tk.PhotoImage(master=master, data=prefix_icon_png(kind, size, foreground), format="png")


class PrefixPreferences(tk.Toplevel):
    def __init__(self, owner, items, save):
        super().__init__(owner)
        self.title(tr("Custom folder prefixes"))
        self.transient(owner)
        self.resizable(True, False)
        self.columnconfigure(2, weight=1)
        self.rows = []
        self.previews = []
        self.images = {key: prefix_icon(self, key) for key in PREFIX_ICONS}
        self.keys = list(PREFIX_ICONS)
        ttk.Label(self, text=tr("Choose up to three prefixes. Empty paths disable a slot.")).grid(
            row=0, column=0, columnspan=4, padx=12, pady=10, sticky="w")
        for index, item in enumerate(items):
            preview = ttk.Label(self, image=self.images[item["icon"]])
            preview.grid(row=index+1, column=0, padx=(12, 4))
            self.previews.append(preview)
            icon = ttk.Combobox(self, state="readonly", width=14,
                               values=[tr(PREFIX_ICONS[key]) for key in self.keys])
            icon.current(self.keys.index(item["icon"]))
            icon.grid(row=index+1, column=1, padx=4, pady=6)
            icon.bind("<<ComboboxSelected>>", lambda _e, c=icon, p=preview:
                      p.configure(image=self.images[self.keys[c.current()]]))
            path = tk.StringVar(value=item["path"])
            ttk.Entry(self, width=48, textvariable=path).grid(row=index+1, column=2, padx=4, sticky="ew")
            def browse(variable=path):
                chosen = filedialog.askdirectory(parent=self)
                if chosen: variable.set(chosen)
            ttk.Button(self, text="…", width=3, command=browse).grid(row=index+1, column=3, padx=(4, 12))
            self.rows.append((icon, path))
        def commit():
            result = []
            for icon, variable in self.rows:
                value = variable.get().strip().strip('"')
                if value:
                    path = Path(os.path.normpath(os.path.expandvars(value))).expanduser()
                    if not path.is_absolute():
                        messagebox.showerror(tr("Custom folder prefixes"), tr("Enter an absolute folder path."), parent=self)
                        return
                    value = str(path)
                result.append({"icon": self.keys[icon.current()], "path": value})
            save(result)
            self.destroy()
        self.save_button = ttk.Button(self, text=tr("Save"), command=commit)
        self.save_button.grid(row=4, column=2, sticky="e", padx=4, pady=10)
        ttk.Button(self, text=tr("Cancel"), command=self.destroy).grid(row=4, column=3, padx=12, pady=10)
        self.bind("<Escape>", lambda _e: self.destroy())

    def apply_scale(self):
        self.images = {key: prefix_icon(self, key) for key in PREFIX_ICONS}
        for preview, (combo, _path) in zip(self.previews, self.rows):
            preview.configure(image=self.images[self.keys[combo.current()]])


