"""Non-hydrating, best-effort Windows OneDrive metadata and bounded async cache.

Only registered OneDrive roots are queried. FASTPROPERTIESONLY deliberately
omits slow provider values; missing metadata is unknown, never 'synced'.
"""
import ctypes
import os
from pathlib import Path
import queue
import threading
import time
import uuid


CLOUD_LABELS = {'online': 'Online only', 'available': 'Locally available',
                'pinned': 'Always available offline', 'syncing': 'Syncing / pending',
                'error': 'Sync error', 'paused': 'Sync paused', 'warning': 'Sync warning'}
CLOUD_DETAILS = {
    'online': 'Light violet triangle: online only; opening may require a download.',
    'available': 'Cyan-blue triangle: local copy is in sync; cleanup may remove the local copy.',
    'pinned': 'Cyan-blue triangle: local copy is in sync and marked to stay offline.',
    'syncing': 'Pending changes are not yet confirmed synchronized.',
    'error': 'Check OneDrive for the error and recovery actions.',
    'paused': 'Check OneDrive to resume synchronization.',
    'warning': 'Check OneDrive for more information.',
}


def cloud_state(attributes, transfer=None, placeholder=None):
    if attributes is None or attributes == 0xffffffff:
        return None
    if transfer is not None:
        if transfer & 0x10:
            return 'error'
        if transfer & 8:
            return 'paused'
        if transfer & (0x80 | 0x100 | 0x200):
            return 'warning'
        if transfer & (1 | 2 | 4 | 0x20 | 0x40):
            return 'syncing'
    if attributes & (0x1000 | 0x40000 | 0x400000):
        return 'online'
    # PINNED is intent; require a complete local primary stream as evidence.
    if placeholder is not None and placeholder & 8 and placeholder & 2:
        return 'pinned' if attributes & 0x80000 else 'available'
    return None


class _CloudGUID(ctypes.Structure):
    _fields_ = [('data', ctypes.c_ubyte * 16)]

    @classmethod
    def parse(cls, text):
        return cls((ctypes.c_ubyte * 16).from_buffer_copy(uuid.UUID(text).bytes_le))


class _CloudPropertyKey(ctypes.Structure):
    _fields_ = [('fmtid', _CloudGUID), ('pid', ctypes.c_uint32)]


class _CloudVariant(ctypes.Structure):
    # PROPVARIANT header followed by the largest pointer-sized union (16B x64).
    _fields_ = [('vt', ctypes.c_uint16), ('reserved', ctypes.c_uint16 * 3),
                ('value', ctypes.c_uint64 * 2)]


def read_cloud_status(path):
    """Called only by the metadata worker; never opens file contents."""
    if os.name != 'nt':
        return None
    kernel = ctypes.windll.kernel32
    kernel.GetFileAttributesW.argtypes = [ctypes.c_wchar_p]
    kernel.GetFileAttributesW.restype = ctypes.c_uint32
    attributes = kernel.GetFileAttributesW(str(path))
    if attributes == 0xffffffff:
        return None
    store = ctypes.c_void_p()
    shell = ctypes.windll.shell32
    shell.SHGetPropertyStoreFromParsingName.argtypes = [ctypes.c_wchar_p, ctypes.c_void_p,
        ctypes.c_uint32, ctypes.POINTER(_CloudGUID), ctypes.POINTER(ctypes.c_void_p)]
    shell.SHGetPropertyStoreFromParsingName.restype = ctypes.c_long
    iid = _CloudGUID.parse('886d8eeb-8cf2-4446-8d02-cdba1dbdcf99')
    hr = shell.SHGetPropertyStoreFromParsingName(str(path), None, 0x48, ctypes.byref(iid), ctypes.byref(store))
    values = [None, None]
    if hr >= 0 and store:
        vtable = ctypes.cast(store, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
        get_value = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p,
            ctypes.POINTER(_CloudPropertyKey), ctypes.POINTER(_CloudVariant))(vtable[5])
        release = ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)(vtable[2])
        clear = ctypes.windll.ole32.PropVariantClear
        clear.argtypes = [ctypes.POINTER(_CloudVariant)]
        try:
            for index, (guid, pid) in enumerate((
                ('fceff153-e839-4cf3-a9e7-ea22832094b8', 103),
                ('b2f9b9d6-fec4-4dd5-94d7-8957488c807b', 2))):
                key = _CloudPropertyKey(_CloudGUID.parse(guid), pid)
                value = _CloudVariant()
                try:
                    if get_value(store, ctypes.byref(key), ctypes.byref(value)) >= 0 and value.vt == 19:
                        values[index] = int(value.value[0] & 0xffffffff)
                finally:
                    clear(ctypes.byref(value))
        finally:
            release(store)
    return cloud_state(attributes, *values)


class CloudStatusCache:
    """One daemon worker, at most 128 visible items/batch; no Tk calls off-thread."""
    def __init__(self, roots, reader=read_cloud_status):
        self.roots = tuple(Path(p) for p in roots)
        self.reader = reader
        self.values = {}
        self.results = queue.Queue(maxsize=1)
        self.busy = False
        self.due = 0
        self.cursor = 0
        self._last_candidates = ()

    def eligible(self, path):
        path = Path(path)
        return any(path == root or root in path.parents for root in self.roots)

    def get(self, path):
        return self.values.get(str(path))

    def poll(self, paths):
        changed = False
        try:
            updates = self.results.get_nowait()
            self.busy = False
            changed = any(self.values.get(key) != value for key, value in updates.items())
            if len(self.values) > 512:
                self.values.clear()
                changed = True
            self.values.update(updates)
        except queue.Empty:
            pass
        now = time.monotonic()
        candidates = list(dict.fromkeys(str(p) for p in paths if self.eligible(p)))
        if tuple(candidates) != self._last_candidates:
            self._last_candidates = tuple(candidates)
            self.cursor = 0
            self.due = 0  # New viewport must not inherit the old folder's timer.
        if self.busy or now < self.due:
            return changed
        start = self.cursor % len(candidates) if candidates else 0
        selected = (candidates[start:] + candidates[:start])[:128]
        self.cursor = start+len(selected)
        self.due = now+2
        if not selected:
            return changed
        self.busy = True
        def work():
            initialized = False
            updates = {}
            try:
                if os.name == 'nt':
                    initialized = ctypes.windll.ole32.CoInitializeEx(None, 2) >= 0
                for path in selected:
                    try:
                        updates[path] = self.reader(path)
                    except (OSError, ValueError, AttributeError):
                        updates[path] = None
            finally:
                if initialized:
                    ctypes.windll.ole32.CoUninitialize()
                self.results.put(updates)
        threading.Thread(target=work, name='PFC-OneDrive-metadata', daemon=True).start()
        return changed


# Source: pycommander/marquee.py
"""A single clipped, font-sized moving name; file identities never change."""
import time
import os
import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk


def forward_tree_event(tree, event, sequence):
    """Keep text overlays transparent to native selection, drag and wheel input."""
    options = dict(x=event.x_root-tree.winfo_rootx(),
                   y=event.y_root-tree.winfo_rooty(),
                   rootx=event.x_root, rooty=event.y_root,
                   state=event.state, time=event.time, when="now")
    if sequence == "<MouseWheel>":
        options["delta"] = event.delta
    tree.event_generate(sequence, **options)
    return "break"


def marquee_offset(elapsed, overflow, speed):
    """One second at the start, forward reading, 1.5 seconds at the end."""
    if overflow <= 0 or speed <= 0:
        return 0.0
    travel = overflow / speed
    phase = max(0, elapsed) % (1.0 + travel + 1.5)
    return min(overflow, max(0, phase - 1.0) * speed)


class NameMarquee:
    def __init__(self, pane):
        self.pane, self.tree = pane, pane.tree
        self.owner = pane.winfo_toplevel()
        self.job = self.pending = None
        self.item = ""
        self.suspended = False
        self.closed = False
        self._forwarding_press = False
        self._last_press = None
        self.canvas = tk.Canvas(self.tree, highlightthickness=0, borderwidth=0,
                                takefocus=0, cursor="arrow")
        self.text_id = self.canvas.create_text(0, 0, anchor="w")
        for sequence in ("<<TreeviewSelect>>", "<FocusIn>", "<KeyRelease>",
                         "<ButtonRelease-1>", "<Configure>", "<Map>",
                         "<<TreeviewOpen>>", "<<TreeviewClose>>"):
            self.tree.bind(sequence, self.request, add="+")
        for sequence in ("<FocusOut>", "<Unmap>"):
            self.tree.bind(sequence, lambda _e: self.stop(), add="+")
        self.tree.bind("<Destroy>", self._destroy, add="+")
        # Forward raw events with their original time/state. Tk itself recognizes
        # double clicks; generating synthetic Double events is not supported.
        for sequence in ("<ButtonPress-1>", "<ButtonRelease-1>",
                         "<ButtonPress-2>", "<ButtonRelease-2>",
                         "<ButtonPress-3>", "<ButtonRelease-3>",
                         "<Motion>", "<MouseWheel>", "<ButtonPress-4>",
                         "<ButtonPress-5>"):
            self.canvas.bind(sequence, lambda e, s=sequence: self._forward(e, s))

    def _forward(self, event, sequence):
        self._forwarding_press = sequence == '<ButtonPress-1>'
        try:
            return forward_tree_event(self.tree, event, sequence)
        finally:
            self._forwarding_press = False

    def pointer_press(self, event):
        """Bridge a double click that crosses the canvas/native row boundary.

        The original canvas events interrupt Tk's native multi-click history.
        Track only gestures involving that overlay; native rows keep Tk's own
        double-click behavior. No synthetic Double event is generated.
        """
        previous = self._last_press
        row = self.tree.identify_row(event.y)
        self._last_press = (event.time, event.x_root, event.y_root, row,
                            self._forwarding_press)
        delay, distance_x, distance_y = 500, 5, 5
        if os.name == 'nt':
            import ctypes
            delay = ctypes.windll.user32.GetDoubleClickTime()
            distance_x = max(2, ctypes.windll.user32.GetSystemMetrics(36))
            distance_y = max(2, ctypes.windll.user32.GetSystemMetrics(37))
        if (previous and row and previous[3] == row
                and (previous[4] or self._forwarding_press)
                and 0 < (event.time-previous[0]) % (2**32) <= delay
                and abs(event.x_root-previous[1]) <= distance_x
                and abs(event.y_root-previous[2]) <= distance_y
                and not event.state & (1 | 4)):
            self._last_press = None
            self.pane._drag_press_item = self.pane._drag_press_xy = None
            self.pane._dragging = False
            self.stop()
            self.tree.selection_set(row)
            self.tree.focus(row)
            self.pane.open_selected()
            return True
        return False

    def request(self, _event=None):
        if self.closed:
            return
        self.stop()
        self.pending = self.tree.after_idle(self.start)

    def stop(self):
        for key in ("job", "pending"):
            job = getattr(self, key)
            if job is not None:
                try: self.tree.after_cancel(job)
                except tk.TclError: pass
                setattr(self, key, None)
        self.item = ""
        try: self.canvas.place_forget()
        except tk.TclError: pass

    def _eligible(self):
        setting = getattr(self.owner, "long_name_scrolling_var", None)
        context = getattr(self.owner, "file_context_menu", None)
        return (not self.closed and not self.suspended and setting is not None and setting.get()
                and getattr(self.owner, "active", None) is self.pane
                and self.owner.state() != "iconic"
                and not (context is not None and context.winfo_exists() and context.winfo_ismapped())
                and self.tree.winfo_ismapped() and self.tree.focus_get() is self.tree
                and not self.tree.grab_current()
                and not self.pane._drag_press_item and not self.pane._dragging
                and self.pane._inline_editor is None)

    def text_bounds(self, iid):
        """Locate native text after indentation, expander and icon (any theme)."""
        box = self.tree.bbox(iid, "#0")
        if not box:
            return None
        x, y, width, height = box
        right = min(x+width-2, self.tree.winfo_width()-2)
        center = y+height//2
        if y < 0 or y+height > self.tree.winfo_height():
            return None
        for left in range(max(2, x), right):
            if self.tree.identify_element(left, center) == "text":
                return left, y+1, right-left, height-2
        return None

    def clipped(self, iid):
        bounds = self.text_bounds(iid)
        return bool(bounds and tkfont.nametofont("TkDefaultFont").measure(
            str(self.tree.item(iid, "text"))) > bounds[2])

    def start(self):
        self.pending = None
        if not self._eligible():
            return
        iid = self.tree.focus()
        if not iid or iid not in self.tree.selection():
            return
        bounds = self.text_bounds(iid)
        if not bounds or bounds[2] <= 0:
            return
        text = str(self.tree.item(iid, "text"))
        font = tkfont.nametofont("TkDefaultFont")
        self.overflow = font.measure(text)-bounds[2]+2
        if self.overflow <= 2:
            return
        self.item = iid
        self.pane._name_tooltip.hide()
        style = ttk.Style(self.tree)
        name = self.tree.cget("style") or "Treeview"
        states = ("selected", "focus")
        palette = getattr(self.owner, "palette", {})
        background = style.lookup(name, "background", states) or palette.get("selection", "#0078d4")
        foreground = style.lookup(name, "foreground", states) or "#ffffff"
        self.canvas.configure(background=background)
        self.canvas.itemconfigure(self.text_id, text=text, font=font, fill=foreground)
        self.canvas.coords(self.text_id, 0, bounds[3]/2)
        self.canvas.place(x=bounds[0], y=bounds[1], width=bounds[2], height=bounds[3])
        self.canvas.tk.call("raise", self.canvas._w)
        self.height = bounds[3]
        self.started = time.monotonic()
        self.speed = 36 * self.owner._font_scales.get(self.owner.font_size_var.get(), 1.0)
        self.job = self.tree.after(33, self.tick)

    def tick(self):
        if self.job is not None:
            self.tree.after_cancel(self.job)
        self.job = None
        if (not self._eligible() or self.tree.focus() != self.item
                or self.item not in self.tree.selection()):
            self.stop()
            return
        offset = marquee_offset(time.monotonic()-self.started, self.overflow, self.speed)
        self.canvas.coords(self.text_id, -offset, self.height/2)
        self.job = self.tree.after(33, self.tick)

    def _destroy(self, event):
        if event.widget is self.tree:
            self.stop()
            self.closed = True


# Source: pycommander/detailcells.py
"""Font-scaled rich size units over native Treeview cells; no polling or I/O."""
import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk





class SizeUnitCells:
    def __init__(self, pane):
        self.pane, self.tree = pane, pane.tree
        self.pending = None
        self.closed = False
        self.cells = []
        self.font = tkfont.nametofont("TkDefaultFont")
        self.bold = tkfont.Font(self.tree, **font_snapshot(self.font))
        self.bold.configure(weight="bold")
        for event in ("<<TreeviewSelect>>", "<FocusIn>", "<FocusOut>",
                      "<Configure>", "<Map>", "<ButtonRelease-1>",
                      "<<TreeviewOpen>>", "<<TreeviewClose>>"):
            self.tree.bind(event, self.request, add="+")
        self.tree.bind("<Unmap>", self.hide, add="+")
        self.tree.bind("<Destroy>", self.destroy, add="+")

    def hide(self, _event=None):
        if self.pending is not None:
            self.tree.after_cancel(self.pending)
            self.pending = None
        for cell in self.cells:
            try:
                cell.place_forget()
            except tk.TclError:
                pass  # Child canvases may already be destroyed with their tree.

    def request(self, _event=None):
        if self.closed or self.pending is not None:
            return
        self.pending = self.tree.after_idle(self.draw)

    def sync_font(self):
        self.bold.configure(**font_snapshot(self.font))
        self.bold.configure(weight="bold")

    def measure(self, text):
        number, _, unit = str(text).rpartition(" ")
        if unit in ("GB", "TB"):
            return self.font.measure(number + " ") + self.bold.measure(unit)
        return self.font.measure(str(text))

    def _cell(self, index):
        if index == len(self.cells):
            cell = tk.Canvas(self.tree, highlightthickness=0, borderwidth=0,
                             takefocus=0, cursor="arrow")
            cell.create_text(0, 0, anchor="e", tags="unit")
            cell.create_text(0, 0, anchor="e", tags="number")
            for sequence in ("<ButtonPress-1>", "<ButtonRelease-1>",
                             "<ButtonPress-2>", "<ButtonRelease-2>",
                             "<ButtonPress-3>", "<ButtonRelease-3>",
                             "<Motion>", "<MouseWheel>", "<ButtonPress-4>",
                             "<ButtonPress-5>"):
                cell.bind(sequence, lambda e, s=sequence: forward_tree_event(self.tree, e, s))
            self.cells.append(cell)
        return self.cells[index]

    def draw(self):
        self.pending = None
        if self.closed:
            return
        if (not self.tree.winfo_ismapped() or 'size' not in self.tree.cget('displaycolumns')
                or not self.pane.winfo_toplevel().size_emphasis_var.get()):
            self.hide()
            return
        font = self.font
        self.sync_font()
        style = ttk.Style(self.tree)
        name = self.tree.cget("style") or "Treeview"
        selected = set(self.tree.selection())
        focused = self.tree.focus_get() is self.tree
        height, width = self.tree.winfo_height(), self.tree.winfo_width()
        # Walk screen rows, not all directory entries (including expanded trees).
        y, used, seen = 1, 0, set()
        while y < height:
            iid = self.tree.identify_row(y)
            if not iid or iid in seen:
                y += 1
                continue
            seen.add(iid)
            box = self.tree.bbox(iid, "size")
            if not box:
                y += 1
                continue
            x, top, cell_width, row_height = box
            y = top + row_height
            text = self.tree.set(iid, "size")
            number, _, unit = text.rpartition(" ")
            if unit not in ("GB", "TB") or x < 0 or x+cell_width > width or top < 0:
                continue
            states = (("selected",) if iid in selected else ()) + (("focus",) if focused else ())
            bg = style.lookup(name, "background", states) or "white"
            fg = style.lookup(name, "foreground", states) or "black"
            # A lighter red remains distinct against both dark and selection backgrounds.
            rgb = self.tree.winfo_rgb(bg)
            luminance = sum(c*w for c, w in zip(rgb, (.2126, .7152, .0722))) / 65535
            red = "#ff8585" if luminance < .5 else "#b00020"
            cell = self._cell(used); used += 1
            cell.configure(background=bg)
            right = cell_width-4
            cell.coords('unit', right, (row_height-2)/2)
            cell.itemconfigure('unit', text=unit, font=self.bold, fill=red if unit == "TB" else fg)
            cell.coords('number', right-self.bold.measure(unit), (row_height-2)/2)
            cell.itemconfigure('number', text=number+" ", font=font, fill=fg)
            cell.place(x=x+1, y=top+1, width=max(1, cell_width-2), height=max(1, row_height-2))
            cell.tk.call("raise", cell._w)
        for cell in self.cells[used:]:
            cell.place_forget()

    def destroy(self, event):
        if event.widget is self.tree:
            self.closed = True
            self.hide()


# Source: pycommander/singlepanel.py
"""Shared tab strip and bounded, on-demand folder navigation for one-panel mode."""
import ctypes
from collections import deque
import os
from pathlib import Path
import queue
import stat
import threading
import time
import tkinter as tk
from tkinter import ttk
import tkinter.font as tkfont







def root_folders():
    # Enumerate drive letters, never probe every drive/share for availability.
    if os.name == 'nt':
        mask = ctypes.windll.kernel32.GetLogicalDrives()
        return [Path(f'{chr(65+i)}:/') for i in range(26) if mask & (1 << i)]
    return [Path('/')]


def child_folders(path, stop, limit=2000, seconds=3):
    """One directory only, no recursive walk and no file-content reads."""
    found, seen, partial = [], 0, False
    deadline = time.monotonic()+seconds
    with os.scandir(path) as entries:
        for entry in entries:
            if stop.is_set() or seen >= limit or time.monotonic() > deadline:
                partial = True
                break
            seen += 1
            try:
                if entry.is_dir(follow_symlinks=False):
                    found.append(Path(entry.path))
            except OSError:
                continue
    return sorted(found, key=lambda p:p.name.casefold()), partial


def folder_has_children(path, stop, limit=2000, seconds=.2):
    """True/False only when verified; None means unknown, not an empty folder.

    A visible-row hint, not a directory index: stop at the first subdirectory,
    never open file contents, and avoid automatically probing drives, shares,
    symlinks or Windows cloud/reparse placeholders.
    """
    if stop.is_set() or path.parent == path or str(path).startswith(('\\\\', '//')):
        return None
    deadline = time.monotonic()+seconds
    try:
        info = path.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & (0x400 | 0x1000):
            return None
        uncertain = False
        with os.scandir(path) as entries:
            for index, entry in enumerate(entries):
                if stop.is_set() or index >= limit or time.monotonic() > deadline:
                    return None
                try:
                    if entry.is_dir(follow_symlinks=False): return True
                except OSError:
                    uncertain = True
        return None if uncertain or stop.is_set() else False
    except OSError:
        return None


def branch_segments(following, expanded, indent, height):
    """Connect actual siblings; an expanded last child still ends its parent line."""
    depth, mid = len(following)-1, height/2
    lines = []
    for level in range(1, depth):
        if following[level]:
            x = (level-.5)*indent
            lines.append((x, 0, x, height))
    if depth:
        x = (depth-.5)*indent
        lines.extend(((x, 0, x, height if following[-1] else mid),
                      (x, mid, (depth+.5)*indent, mid)))
    if expanded:
        x = (depth+.5)*indent
        lines.append((x, mid, x, height))
    return lines


class RootFolderTree(ttk.Frame):
    EXPAND_SECONDS = 30
    EXPAND_FOLDERS = 500
    EXPAND_DEPTH = 32

    def __init__(self, master, on_navigate, on_context):
        super().__init__(master)
        # The splitter owns our size. A tall floating ancestry must not grow
        # the pane's requested height and push the app's bottom controls away.
        self.configure(width=240, height=240)
        self.pack_propagate(False)
        self.on_navigate = on_navigate
        self.on_context = on_context
        header = ttk.Frame(self); header.pack(fill='x', padx=6, pady=4)
        self.caption = ttk.Label(header, text=tr('Folders'))
        self.caption.pack(side='left')
        self.expand_all_var = tk.BooleanVar(self, value=False)
        self.expand_all_button = ttk.Checkbutton(header, text=tr('Expand All'),
            variable=self.expand_all_var, command=self.toggle_expand_all)
        self.expand_all_button.pack(side='right', padx=(8,0))
        ToolTip(self.expand_all_button, lambda: tr('Expand descendants of the current folder. Uncheck to stop.'))
        self._sticky = tk.Canvas(self, height=0, highlightthickness=0, borderwidth=0,
                                 takefocus=False, cursor='hand2')
        self._sticky_chain = ()
        self._sticky_rows = []
        self._sticky_height = 0
        self._sticky_signature = None
        self._sticky_font = tkfont.Font(self, font='TkDefaultFont')
        self._sticky_icons = {}
        self._sticky.bind('<Button-1>', self._sticky_click)
        self._sticky.bind('<Double-Button-1>', lambda _e:'break')
        for event in ('<MouseWheel>', '<Button-4>', '<Button-5>'):
            self._sticky.bind(event, self._line_wheel)
        self._sticky.bind('<Motion>', self._sticky_motion)
        self._sticky_tip = ''
        ToolTip(self._sticky, lambda: self._sticky_tip)
        body = self._body = ttk.Frame(self); body.pack(fill='both', expand=True)
        self.tree = ttk.Treeview(body, show='tree', selectmode='browse', style='FolderNav.Treeview')
        self._row_images = {}
        self._image_cache = {}
        self._line_signature = None
        self._line_indent = None
        self._line_job = None
        self._drawing_lines = False
        self._view_epoch = 0
        self._view_settle_job = None
        scroll = ttk.Scrollbar(body, command=self._scroll_view)
        scroll.pack(side='right', fill='y'); self.tree.pack(fill='both', expand=True)
        self.tree.configure(yscrollcommand=lambda *args:self._scrolled(scroll, *args))
        horizontal = self._horizontal = ttk.Scrollbar(self, orient='horizontal', command=self.tree.xview)
        horizontal.pack(side='bottom', fill='x')
        self.tree.configure(xscrollcommand=lambda *args:self._scrolled(horizontal, *args))
        self.status = ttk.Label(self, text='', wraplength=280)
        self.status.pack(side='bottom', fill='x', padx=4)
        # Reserve the bottom controls before giving the tree its remaining area.
        body.pack_forget(); body.pack(fill='both', expand=True)
        self.paths, self.nodes, self.loaded, self.pending = {}, {}, set(), {}
        self.failed, self.partial = set(), set()
        self._child_hints = {}  # absent = not checked; None = inconclusive
        self._probe_results = queue.Queue()
        self._probe_cancel = None
        self._visible_nodes = ()
        self._context_queue = deque()
        self._bulk_queue = deque(); self._bulk_seen = set(); self._bulk_pending = set(); self._bulk_checked = set()
        self._bulk_running = False; self._bulk_incomplete = False
        self._current_node = None
        self._icons = {kind: tk.PhotoImage(master=self, data=folder_nav_icon_png(kind, 16), format='png')
                       for kind in ('folder', 'drive', 'pc')}
        self._icon_size = 16
        self.results = queue.Queue(); self.slots = threading.BoundedSemaphore(2)
        self.stop = threading.Event(); self.serial = 0; self.program_selection = None
        self.pc = self.tree.insert('', 'end', text=tr('This PC'), open=True)
        for path in root_folders(): self._node(path, self.pc)
        self.tree.bind('<<TreeviewOpen>>', self._expand)
        self.tree.bind('<<TreeviewSelect>>', self._select)
        self._press_node = None
        self._press_open = False
        self.tree.bind('<Button-1>', self._native_click)
        for event in ('<MouseWheel>', '<Button-4>', '<Button-5>', '<KeyPress>'):
            self.tree.bind(event, self._cancel_view_settle, add='+')
        self.tree.bind('<Double-Button-1>', self._double_click)
        self.tree.bind('<<TreeviewClose>>', self._manual_collapse, add='+')
        self.tree.bind('<Button-3>', on_context)
        self.tree.bind('<Shift-F10>', on_context)
        self.tree.bind('<KeyPress-Menu>', on_context)
        self.tree.bind('<Configure>', self._redraw_lines, add='+')
        for event in ('<Expose>', '<<TreeviewOpen>>', '<<TreeviewClose>>', '<<TreeviewSelect>>'):
            self.tree.bind(event, self._schedule_lines, add='+')
        # Run AFTER native Treeview input but BEFORE it paints. An after_idle
        # callback is too late: native text has already moved while the child
        # canvases still show the previous row's selection/icon. Preserve Tk's
        # platform-specific wheel and keyboard behaviour instead of duplicating it.
        self._render_tag = f'PFCFolderRender{id(self)}'
        tags = list(self.tree.bindtags())
        tags.insert(tags.index('Treeview')+1, self._render_tag)
        self.tree.bindtags(tuple(tags))
        for event in ('<MouseWheel>', '<Shift-MouseWheel>', '<Button-4>', '<Button-5>',
                      '<Shift-Button-4>', '<Shift-Button-5>', '<KeyPress>',
                      '<Button-1>', '<ButtonRelease-1>'):
            self.tree.bind_class(self._render_tag, event, self._redraw_lines)
        # These belong to the file list, never silently operate on its old row
        # while the navigation tree has focus. Arrow keys keep native tree use.
        for key in ('<Delete>', '<Shift-Delete>', '<F2>', '<Control-c>', '<Control-x>'):
            self.tree.bind(key, lambda _e:'break')
        self._poll_job = self.after(80, self._poll)
        self.bind('<Unmap>', lambda e: self.stop_expand_all() if e.widget is self else None)

    def _schedule_lines(self, _event=None):
        if self._line_job is None:
            self._line_job = self.after_idle(self._redraw_lines)

    def _redraw_lines(self, _event=None):
        if self._drawing_lines: return
        if self._line_job is not None:
            self.after_cancel(self._line_job)
            self._line_job = None
        self._drawing_lines = True
        try:
            self._draw_lines()
        finally:
            self._drawing_lines = False

    def _scrolled(self, scrollbar, *args):
        scrollbar.set(*args)
        # Also cover scrollbar drags, see(), and programmatic x/yview changes.
        # Tk calls this while preparing its new viewport, before native paint.
        self._redraw_lines()

    def _remember_press(self, event, iid=None):
        self._cancel_view_settle()
        self._press_node = iid if iid is not None else self.tree.identify_row(event.y)
        self._press_open = bool(self.tree.item(self._press_node, 'open')) if self._press_node else False

    def _native_click(self, event):
        self._remember_press(event)
        iid = self._press_node
        if not iid or not self._has_branch(iid) or self.tree.item(iid, 'open'): return
        box = self.tree.bbox(iid)
        if not box or not self._line_indent: return
        depth, parent = 0, self.tree.parent(iid)
        while parent:
            depth += 1; parent = self.tree.parent(parent)
        center = box[0]+(depth+.5)*self._line_indent
        radius = max(3, min(5, round(self._line_indent*.13)))
        plus_x = round(center)+round(self._icon_size*.28)
        plus_y = box[1]+box[3]//2+round(self._icon_size*.26)
        if abs(event.x-plus_x) <= radius and abs(event.y-plus_y) <= radius:
            self.tree.focus_set(); self.tree.focus(iid)
            self.tree.item(iid, open=True)
            self.failed.discard(iid); self.load(iid)
            self._redraw_lines()
            return 'break'

    def _manual_collapse(self, _event=None):
        # Manual intent wins over an in-flight/completed Expand All action.
        if self.expand_all_var.get(): self.stop_expand_all()

    def _double_click(self, event):
        iid = self._press_node
        if not iid or not self.tree.exists(iid): return 'break'
        self._manual_collapse()
        self.tree.focus_set(); self.tree.focus(iid)
        # Single-click navigation may already have opened this node. Toggle the
        # state at the FIRST press, not that incidental intermediate state.
        opening = not self._press_open
        self.tree.item(iid, open=opening)
        if opening:
            self.failed.discard(iid)
            self.load(iid)
        self._draw_lines()
        # Suppress ttk's second toggle and focus/see handling.
        return 'break'

    def _line_wheel(self, event):
        self._cancel_view_settle()
        if getattr(event, 'num', None) in (4, 5):
            self.tree.yview_scroll(-3 if event.num == 4 else 3, 'units')
        else:
            self.tree.event_generate('<MouseWheel>', delta=event.delta, state=event.state)
        self._redraw_lines()
        return 'break'

    def _cancel_view_settle(self, _event=None):
        self._view_epoch += 1
        if self._view_settle_job is not None:
            self.after_cancel(self._view_settle_job)
            self._view_settle_job = None

    def _scroll_view(self, *args):
        self._cancel_view_settle()
        self.tree.yview(*args)
        self._redraw_lines()

    def _sticky_motion(self, event):
        row = next((iid for top, bottom, iid in self._sticky_rows if top <= event.y < bottom), '')
        if row and not self.tree.exists(row): row = ''
        self._sticky_tip = str(self.paths.get(row, self.tree.item(row, 'text'))) if row else ''

    def _reveal_ancestor(self, iid):
        if not self.tree.exists(iid): return
        self.tree.focus_set(); self.tree.focus(iid)
        self.tree.selection_set(iid)
        self.tree.see(iid)
        self._schedule_lines()

    def _sticky_click(self, event):
        for top, bottom, iid in self._sticky_rows:
            if not top <= event.y < bottom: continue
            self._reveal_ancestor(iid)
            break
        return 'break'

    def _draw_sticky(self, rows, width, height, indent, bg, fg, font):
        # Only the ancestors of the first visible row describe this viewport;
        # selection may be elsewhere. No traversal/scanning of other subtrees.
        chain = []
        if rows:
            item = self.tree.parent(rows[0][0])
            while item:
                chain.append(item); item = self.tree.parent(item)
            chain.reverse()
        self._sticky_chain = tuple(chain)
        if not chain:
            self._sticky.pack_forget()
            self._sticky_height = 0
            self._sticky_rows = []
            self._sticky_signature = None
            return
        normal_height = rows[0][3]
        # Never omit ancestors. Very deep paths use a denser context band while
        # leaving two ordinary tree rows available for navigation.
        actual_band = self._sticky.winfo_height() if self._sticky.winfo_ismapped() else 0
        available = max(1, self._body.winfo_height()+actual_band-2*normal_height-4)
        row_height = min(normal_height, max(1, int(available)//len(chain)))
        band_height = round(len(chain)*row_height)+1
        x = rows[0][1]
        following = tuple(bool(self.tree.next(item)) for item in chain)
        signature = (tuple(chain), following, width, row_height, indent, x,
                     bg, fg, tuple(sorted(font.actual().items())),
                     tuple(self.tree.item(i, 'text') for i in chain))
        if signature == self._sticky_signature: return
        self._sticky_signature = signature
        self._sticky_height = band_height
        self._sticky_font.configure(**font.actual())
        if row_height < font.metrics('linespace')+4:
            self._sticky_font.configure(size=-max(1, int(row_height-4)))
        icon_size = max(1, min(self._icon_size, int(row_height-3)))
        if icon_size == self._icon_size:
            self._sticky_icons = {'size':icon_size, 'shared':True, **self._icons}
        elif self._sticky_icons.get('shared') or self._sticky_icons.get('size') != icon_size:
            self._sticky_icons = {'size':icon_size, **{
                kind:tk.PhotoImage(master=self,data=folder_nav_icon_png(kind,icon_size),format='png')
                for kind in ('pc','drive','folder')}}
        font = self._sticky_font
        ink, paper = self.winfo_rgb(fg), self.winfo_rgb(bg)
        tint = '#'+''.join(f'{round((a*.06+b*.94)/257):02x}' for a,b in zip(ink,paper))
        muted = '#'+''.join(f'{round((a*.48+b*.52)/257):02x}' for a,b in zip(ink,paper))
        canvas = self._sticky
        canvas.configure(height=band_height, background=tint)
        canvas.pack(before=self._body, fill='x', padx=(0, max(0,self._body.winfo_width()-width)))
        canvas.delete('all'); self._sticky_rows = []
        for index, iid in enumerate(chain):
            top, mid = index*row_height, (index+.5)*row_height
            self._sticky_rows.append((top, top+row_height, iid))
            depth = index
            joint = round(x+(depth+.5)*indent)
            # Horizontal scrolling or extreme indentation can put the joint
            # outside the viewport. Keep its context readable at the edge.
            center = joint
            if joint < icon_size/2 or joint > width-icon_size/2:
                clipped_left = joint < icon_size/2
                center = round(max(icon_size/2+6,
                                   min(joint,width-max(100,indent*3))))
                canvas.create_text(3 if clipped_left else width-4,mid,
                                   text='‹' if clipped_left else '›',font=font,fill=muted,
                                   anchor='w' if clipped_left else 'e',tags='ancestor-offscreen')
            for x1, y1, x2, y2 in branch_segments(following[:index+1], True, indent, row_height):
                canvas.create_line(round(x+x1),top+y1,round(x+x2),top+y2,
                                   fill=muted,dash=(1,2),tags='ancestor-branch')
            path = self.paths.get(iid)
            kind = 'pc' if iid == self.pc else 'drive' if path and path.parent == path else 'folder'
            canvas.create_image(center,round(mid),image=self._sticky_icons[kind],tags='ancestor-icon')
            canvas.create_text(round(center+indent/2+4),mid,
                               text=self.tree.item(iid,'text'),font=font,fill=fg,anchor='w',
                               tags='ancestor-name')
        canvas.create_line(0,band_height-1,width,band_height-1,fill=muted,tags='ancestor-edge')

    def _draw_lines(self):
        """Use native item images: icon, text and selection scroll as ONE row.

        No child windows cover Treeview. Transparent image prefixes contain
        the dotted connectors and icon; ttk owns the entire selection surface.
        """
        if not self.tree.winfo_viewable(): return
        style = ttk.Style(self)
        font = tkfont.nametofont('TkDefaultFont')
        icon_size = max(14, round(font.metrics('linespace')*.9))
        if icon_size != self._icon_size:
            self._icon_size = icon_size
            for kind, icon in self._icons.items():
                icon.configure(data=folder_nav_icon_png(kind, icon_size), format='png')
            self._line_signature = None
        indent = max(20, round(font.metrics('linespace')*1.1))
        if indent != self._line_indent:
            self._line_indent = indent
            self._line_signature = None
        if str(style.lookup('FolderNav.Treeview', 'indent')) != '0':
            style.configure('FolderNav.Treeview', indent=0)
        layout = [('Treeitem.padding', {
            'sticky':'nswe', 'children':[
                ('Treeitem.image', {'side':'left', 'sticky':''}),
                ('Treeitem.text', {'side':'left', 'sticky':''})]} )]
        if style.layout('FolderNav.Treeview.Item') != layout:
            style.layout('FolderNav.Treeview.Item', layout)
        height, width = self.tree.winfo_height(), self.tree.winfo_width()
        selected = self.tree.selection()
        bg = style.lookup('FolderNav.Treeview', 'background') or '#ffffff'
        fg = style.lookup('FolderNav.Treeview', 'foreground') or '#303030'
        selbg = style.lookup('FolderNav.Treeview', 'background', ('selected',)) or '#3478bb'
        selfg = style.lookup('FolderNav.Treeview', 'foreground', ('selected',)) or '#ffffff'
        rows, seen = [], set()
        # Probe screen rows, not every expanded node in the cached directory tree.
        y = 1
        while y < height:
            iid = self.tree.identify_row(y)
            if not iid or iid in seen:
                y += 1; continue
            seen.add(iid)
            bbox = self.tree.bbox(iid)
            if not bbox: y += 1; continue
            x, top, _w, h = bbox
            chain, item = [], iid
            while item:
                chain.append(item); item = self.tree.parent(item)
            chain.reverse()
            flags = tuple(bool(self.tree.next(item)) for item in chain)
            actual_children = any(child in self.paths for child in self.tree.get_children(iid))
            children = actual_children or self._child_hints.get(iid) is True
            opened = bool(self.tree.item(iid, 'open'))
            rows.append((iid, x, top, h, flags, children, opened, actual_children, iid in selected))
            y = max(y+1, top+h)
        self._visible_nodes = tuple(row[0] for row in rows)
        self._draw_sticky(rows, width, height, indent, bg, fg, font)
        signature = (tuple(rows), width, height, indent, bg, fg, selbg, selfg)
        if signature == self._line_signature: return
        self._line_signature = signature
        for iid, x, top, h, flags, children, opened, actual_children, active in rows:
            path = self.paths.get(iid)
            kind = 'pc' if iid == self.pc else 'drive' if path and path.parent == path else 'folder'
            key = (flags, opened and actual_children, children and not opened,
                   kind, indent, h, self._icon_size, bg, fg)
            image = self._image_cache.get(key)
            if image is None:
                image = self._prefix_image(*key)
                if len(self._image_cache) >= 512: self._image_cache.clear()
                self._image_cache[key] = image
            if self._row_images.get(iid) is not image:
                self._row_images[iid] = image
                self.tree.item(iid, image=image)

    def _prefix_image(self, flags, expanded, expandable, kind, indent, height, icon_size, bg, fg):
        image = tk.PhotoImage(master=self, width=len(flags)*indent, height=height)
        ink, paper = self.winfo_rgb(fg), self.winfo_rgb(bg)
        muted = '#'+''.join(f'{round((a*.48+b*.52)/257):02x}' for a,b in zip(ink,paper))
        for x1,y1,x2,y2 in branch_segments(flags, expanded, indent, height):
            if x1 == x2:
                for y in range(round(y1), min(height, round(y2)+1), 3):
                    image.put(muted, (round(x1), y))
            else:
                for x in range(round(x1), round(x2)+1, 3):
                    image.put(muted, (x, round(y1)))
        center, mid = round((len(flags)-.5)*indent), height//2
        # Tk can report the previous row height while a new font/icon size is
        # already active. Clip that transitional frame instead of passing a
        # negative destination to PhotoImage.copy and stopping the scan poller.
        icon = self._icons[kind]
        left, top = center-icon_size//2, mid-icon_size//2
        x0, y0 = max(0, -left), max(0, -top)
        x1, y1 = min(icon.width(), image.width()-left), min(icon.height(), height-top)
        if x1 > x0 and y1 > y0:
            self.tk.call(str(image), 'copy', str(icon), '-from', x0, y0, x1, y1,
                         '-to', max(0, left), max(0, top), '-compositingrule', 'overlay')
        if expandable:
            r = max(3, min(5, round(indent*.13)))
            px, py = center+round(icon_size*.28), mid+round(icon_size*.26)
            for color, box in ((muted, (px-r, py-r, px+r+1, py+r+1)),
                               (bg, (px-r+1, py-r+1, px+r, py+r)),
                               (fg, (px-r+2, py, px+r-1, py+1)),
                               (fg, (px, py-r+2, px+1, py+r-1))):
                a, b, c, d = box
                a, b, c, d = max(0, a), max(0, b), min(image.width(), c), min(height, d)
                if c > a and d > b: image.put(color, (a, b, c, d))
        return image

    def _has_branch(self, iid):
        return (self._child_hints.get(iid) is True or
                any(child in self.paths for child in self.tree.get_children(iid)))

    def _probe_visible(self):
        # Independent single worker: a slow hint must never monopolize the two
        # navigation workers. A blocked OS call cannot create more threads.
        if self._probe_cancel is not None or not self.tree.winfo_viewable(): return
        candidates = []
        for iid in self._visible_nodes:
            if (iid not in self.paths or iid in self.loaded or iid in self.pending
                    or iid in self.failed or iid in self._child_hints
                    or self.tree.item(iid, 'open') or self._has_branch(iid)):
                continue
            candidates.append((iid, self.paths[iid]))
            if len(candidates) >= 32: break
        if not candidates: return
        cancel = self._probe_cancel = threading.Event()
        def work():
            deadline = time.monotonic()+1
            try:
                for iid, path in candidates:
                    if cancel.is_set() or self.stop.is_set() or time.monotonic() > deadline: break
                    value = folder_has_children(path, cancel)
                    self._probe_results.put((cancel, iid, value))
            finally:
                self._probe_results.put((cancel, None, None))
        threading.Thread(target=work, daemon=True, name='PFC-folder-hints').start()

    def _poll_probes(self):
        while not self._probe_results.empty():
            cancel, iid, value = self._probe_results.get_nowait()
            if cancel is not self._probe_cancel: continue
            if iid is None:
                self._probe_cancel = None
                continue
            if (cancel.is_set() or iid not in self.paths or iid in self.loaded
                    or iid in self.pending or self._has_branch(iid)):
                continue
            self._child_hints[iid] = value
            if value is False:
                # Remove only the keyboard-expansion placeholder, never a real
                # child inserted by navigation while a hint was in flight.
                for child in self.tree.get_children(iid):
                    if child not in self.paths: self.tree.delete(child)

    def _node(self, path, parent):
        key = os.path.normcase(str(path))
        if key in self.nodes: return self.nodes[key]
        iid = self.tree.insert(parent, 'end', text=path.name or str(path))
        self.paths[iid] = path; self.nodes[key] = iid
        self.tree.insert(iid, 'end', text='…')
        return iid

    def sync(self, path):
        path = Path(path)
        if not path.is_absolute(): return
        existing = self.nodes.get(os.path.normcase(str(path)))
        if existing is not None and existing == self._current_node:
            # Autosave/refresh repeatedly sync the same path. They must not undo
            # a manual collapse, reset tree selection, or scroll back to it.
            return
        if existing and self.tree.selection() == (existing,):
            # A native tree click selects the row BEFORE navigation calls sync.
            # Still update the expansion boundary and cancel the previous run.
            if existing != self._current_node:
                self.stop_expand_all()
                self._current_node = existing
            self.program_selection = existing
            self.tree.item(existing, open=True)
            self._queue_context(existing)
            return
        chain = list(reversed(path.parents))+[path]
        parent = self.pc
        for part in chain:
            parent = self._node(part, parent)
            if part != path:
                # Seed the known path immediately, without showing dummy rows.
                # Background one-level scans will fill in its actual siblings.
                for child in self.tree.get_children(parent):
                    if child not in self.paths: self.tree.delete(child)
                self.tree.item(parent, open=True)
        self.program_selection = parent
        if parent != self._current_node:
            self.stop_expand_all()
            self._current_node = parent
        # Fill each expanded level, never recurse into unrelated descendants.
        self.tree.item(parent, open=True)
        self._queue_context(parent)
        if self.tree.selection() != (parent,): self.tree.selection_set(parent)
        self.tree.focus(parent)
        self.tree.see(parent)
        self._cancel_view_settle()
        self._view_settle_job = self.after_idle(self._settle_scan_selection, parent, self._view_epoch, 32)

    def _queue_context(self, iid):
        # Active folder first, then nearest ancestors. Keep work bounded to the
        # current path and retry queued levels when the two workers are busy.
        self._context_queue.clear()
        while iid in self.paths:
            self._context_queue.append(iid)
            iid = self.tree.parent(iid)
        self._load_context()

    def _load_context(self):
        while self._context_queue:
            iid = self._context_queue[0]
            if (iid not in self.paths or iid in self.loaded or iid in self.failed
                    or iid in self.pending or not self.tree.item(iid, 'open')):
                self._context_queue.popleft()
                continue
            if len(self.nodes) >= 10000:
                self._context_queue.clear()
                self.status.configure(text=tr('Folder tree limit reached. Refresh to reload.'))
                return
            if not self.load(iid, quiet_busy=True): return
            self._context_queue.popleft()

    def _select(self, _event=None):
        selected = self.tree.selection()
        if not selected or selected[0] == self.program_selection: return
        self.program_selection = None
        path = self.paths.get(selected[0])
        if path is not None: self.on_navigate(path)

    def _expand(self, _event=None):
        self.failed.discard(self.tree.focus())
        self.load(self.tree.focus())

    def load(self, iid, bulk=False, quiet_busy=False):
        if iid not in self.paths or iid in self.pending: return
        if not bulk and (iid in self.loaded or iid in self.failed): return
        if len(self.nodes) >= 10000:
            self.status.configure(text=tr('Folder tree limit reached. Refresh to reload.')); return
        if not self.slots.acquire(blocking=False):
            if not quiet_busy:
                self.status.configure(text=tr('Folder scan busy. Try expanding again.'))
            return
        self.serial += 1
        token, path = self.serial, self.paths[iid]
        cancel = threading.Event()
        self.pending[iid] = (token, time.monotonic(), cancel)
        if bulk: self._bulk_pending.add(iid)
        else: self.status.configure(text=tr('Loading folders…'))
        self.failed.discard(iid)
        # Workers never touch Tk. Two daemon workers maximum, even if an offline
        # drive blocks a system call; stale/late results are ignored.
        def work():
            try:
                # Keep cloud/link folders visible for manual navigation, but
                # never follow them automatically during recursive expansion.
                if bulk and (path.is_symlink() or (os.name == 'nt' and
                        path.lstat().st_file_attributes & 0x400)):
                    raise OSError(tr('Linked or cloud folders are skipped during Expand All.'))
                values, partial = child_folders(path, cancel)
                result = (values, partial, '')
            except Exception as exc:
                result = ([], False, str(exc))
            finally:
                self.slots.release()
            if not self.stop.is_set(): self.results.put((iid, token, result))
        threading.Thread(target=work, daemon=True, name='PFC-folder-tree').start()
        return True

    def toggle_expand_all(self):
        if not self.expand_all_var.get():
            self.stop_expand_all()
            return
        anchor = self._current_node
        if anchor not in self.paths:
            self.expand_all_var.set(False)
            return
        self._bulk_queue = deque([(anchor, 0)]); self._bulk_seen.clear()
        self._bulk_checked.clear()
        self._bulk_deadline = time.monotonic()+self.EXPAND_SECONDS
        self._bulk_running = True; self._bulk_incomplete = False
        self.status.configure(text=tr('Expanding folders…'))

    def stop_expand_all(self, message=''):
        self._bulk_running = False
        self.expand_all_var.set(False)
        self._bulk_queue.clear()
        for iid in self._bulk_pending:
            pending = self.pending.pop(iid, None)
            if pending: pending[2].set()
        self._bulk_pending.clear()
        self.status.configure(text=tr(message) if message else '')

    def _expand_batch(self):
        if not self._bulk_running: return
        if time.monotonic() >= self._bulk_deadline or len(self.nodes) >= 10000:
            self.stop_expand_all('Expansion limited. Expand individual folders or refresh to continue.')
            return
        # Bound both filesystem concurrency and Tk work per event-loop turn.
        for _ in range(24):
            if not self._bulk_queue:
                self._bulk_running = False
                self.status.configure(text=tr('Some folders could not be expanded.') if self._bulk_incomplete else '')
                return
            iid, depth = self._bulk_queue.popleft()
            if iid in self._bulk_seen or not self.tree.exists(iid): continue
            if depth > self.EXPAND_DEPTH or len(self._bulk_seen) >= self.EXPAND_FOLDERS:
                self.stop_expand_all('Expansion limited. Expand individual folders or refresh to continue.')
                return
            if iid in self.failed:
                self._bulk_incomplete = True; self._bulk_seen.add(iid)
                continue
            if iid not in self.loaded or iid not in self._bulk_checked:
                self._bulk_queue.appendleft((iid, depth))
                if iid not in self.pending: self.load(iid, bulk=True)
                return
            self._bulk_seen.add(iid)
            self._bulk_incomplete |= iid in self.partial
            self.tree.item(iid, open=True)
            self._bulk_queue.extend((child, depth+1) for child in self.tree.get_children(iid) if child in self.paths)

    def _poll(self):
        self._poll_probes()
        for iid, (token, started, cancel) in list(self.pending.items()):
            if time.monotonic()-started > 5:
                self.pending.pop(iid, None)
                cancel.set(); self.failed.add(iid); self._bulk_pending.discard(iid)
                self.status.configure(text=tr('Folder scan timed out. Try expanding again.'))
        anchor = None
        while not self.results.empty():
            iid, token, (paths, partial, error) = self.results.get_nowait()
            if iid not in self.pending or self.pending[iid][0] != token: continue
            self.pending.pop(iid, None)
            if iid in self._bulk_pending: self._bulk_checked.add(iid)
            self._bulk_pending.discard(iid)
            if not self.tree.exists(iid): continue
            if anchor is None: anchor = self._view_anchor()
            for child in self.tree.get_children(iid):
                if child not in self.paths: self.tree.delete(child)
            for path in paths:
                if len(self.nodes) >= 10000: partial = True; break
                self._node(path, iid)
            # A saved path may already have seeded one child before this scan.
            # Merge in place, sorted, preserving IDs, open states and selection.
            children = self.tree.get_children(iid)
            ordered = sorted(children, key=lambda child: self.tree.item(child, 'text').casefold())
            if tuple(ordered) != children: self.tree.set_children(iid, *ordered)
            if not error: self.loaded.add(iid)
            else: self.failed.add(iid)
            self._child_hints[iid] = (True if self.tree.get_children(iid) else
                                      None if error or partial else False)
            if partial: self.partial.add(iid)
            self.status.configure(text=error or (tr('Folder list limited. Use the file list or Refresh.') if partial else ''))
            if error and not self.tree.get_children(iid): self.tree.insert(iid, 'end', text='…')
        if anchor is not None: self._restore_view_anchor(anchor)
        self._load_context()
        self._expand_batch()
        self._draw_lines()
        self._probe_visible()
        if anchor is not None and self.tree.selection() == (anchor[0],):
            self._cancel_view_settle()
            self._view_settle_job = self.after_idle(self._settle_scan_selection, anchor[0], self._view_epoch, 32)
        self._poll_job = self.after(80, self._poll)

    def _settle_scan_selection(self, iid, epoch, remaining):
        # A new floating ancestry changes the viewport AFTER Tk lays it out.
        # Keep the previously visible row whole, but never fight user scrolling,
        # keyboard navigation, a changed selection or a collapsed branch.
        self._view_settle_job = None
        if (not remaining or epoch != self._view_epoch or not self.tree.winfo_viewable()
                or not self.tree.exists(iid) or self.tree.selection() != (iid,)):
            return
        box = self.tree.bbox(iid)
        if box and box[1] >= 1 and box[1]+box[3] < self.tree.winfo_height(): return
        parent = self.tree.parent(iid)
        while parent:
            if not self.tree.item(parent, 'open'): return
            parent = self.tree.parent(parent)
        self.tree.see(iid)
        self._draw_lines()
        self._view_settle_job = self.after_idle(self._settle_scan_selection, iid, epoch, remaining-1)

    def _view_anchor(self):
        # Keep a visible selection at its screen row while ancestors gain
        # siblings. If the user scrolled away, preserve their top row instead.
        for iid in (*self.tree.selection(), self.tree.identify_row(1)):
            if not iid: continue
            box = self.tree.bbox(iid)
            if box and 0 <= box[1] < self.tree.winfo_height():
                return iid, max(0, (box[1]-1)//box[3])

    def _restore_view_anchor(self, anchor):
        iid, offset = anchor
        if not self.tree.exists(iid): return
        # Cached Tk nodes only, and only after a scan changes the tree. Never
        # enumerate the filesystem or rescan every node on ordinary redraws.
        stack = list(reversed(self.tree.get_children('')))
        position = 0
        while stack:
            item = stack.pop()
            if item == iid:
                self.tree.yview(max(0, position-offset))
                return
            position += 1
            if self.tree.item(item, 'open'):
                stack.extend(reversed(self.tree.get_children(item)))

    def refresh(self):
        # Explicit refresh bounds cache lifetime and picks up drive/folder changes.
        selected = self.tree.selection()
        path = self.paths.get(selected[0]) if selected else None
        self.stop_expand_all()
        if self._probe_cancel is not None: self._probe_cancel.set()
        self._child_hints.clear(); self._visible_nodes = ()
        for _, _, cancel in self.pending.values(): cancel.set()
        self.pending.clear(); self.loaded.clear(); self.paths.clear(); self.nodes.clear()
        self._context_queue.clear()
        self.failed.clear(); self.partial.clear(); self._current_node = None
        self.tree.delete(*self.tree.get_children(self.pc))
        self._row_images.clear(); self._image_cache.clear()
        for drive in root_folders(): self._node(drive, self.pc)
        if path is not None:
            self.sync(path)
            self.load(self.nodes[os.path.normcase(str(path))])

    def destroy(self):
        self._cancel_view_settle()
        self.stop_expand_all()
        if self._probe_cancel is not None: self._probe_cancel.set()
        for _, _, cancel in self.pending.values(): cancel.set()
        self.stop.set()
        self.after_cancel(self._poll_job)
        if self._line_job is not None: self.after_cancel(self._line_job)
        for event in self.tree.bind_class(self._render_tag):
            self.tree.unbind_class(self._render_tag, event)
        super().destroy()


class SharedTabBar(ChamferNotebook):
    """Present existing FilePanes without reparenting, copying or closing them."""
    def __init__(self, master, owner):
        self.owner = owner
        super().__init__(master, tab_style=owner.tab_style_var.get(),
                         on_color_changed=self._color_changed,
                         on_lock_changed=self._lock_changed,
                         on_tabs_reordered=owner.save_config)

    def sync(self, panes, active):
        self._tabs = [p for p in self._tabs if p in panes]
        self._tabs.extend(p for p in panes if p not in self._tabs)
        self._texts = {p:self.owner._tabs_for(p)._texts.get(p, '') for p in self._tabs}
        self._colors = {p:self.owner._tabs_for(p)._colors.get(p, 'default') for p in self._tabs}
        self._locks = {p:p.lock_mode for p in self._tabs}
        self._selected = active if active in self._tabs else (self._tabs[0] if self._tabs else None)
        self._draw()

    def select(self, tab=None):
        if tab is None: return str(self._selected) if self._selected is not None else ''
        pane = self._resolve(tab)
        self.owner._select_single_tab(pane)
        self._see_tab(pane)
        return str(pane)

    def current(self): return self._selected

    def _group_identity(self, child):
        return self.owner._tabs_for(child).panel_number, getattr(child,'tab_group','')

    def _color_changed(self, pane, value):
        self.owner._tabs_for(pane).set_color(pane, value)

    def _lock_changed(self, pane, value):
        self.owner._tabs_for(pane).set_lock(pane, value)


# Source: pycommander/windowplacement.py
"""Recover an unreachable main window without disturbing normal monitor placement."""
import ctypes
from ctypes import wintypes
import os
import tkinter as tk


def popup_work_area(owner):
    """Use the owner's monitor work area, excluding native taskbars/docks."""
    root = owner._root()
    guard = getattr(root, '_window_visibility', None)
    backend = getattr(guard, 'backend', None)
    if backend is not None:
        try:
            state = backend.snapshot()
            if state:
                rect, areas, _margin = state
                cx, cy = (rect[0]+rect[2])/2, (rect[1]+rect[3])/2
                return next((a for a in areas if a[0] <= cx < a[2] and a[1] <= cy < a[3]), areas[0])
        except (OSError, tk.TclError, IndexError):
            pass
    return (0, 0, owner.winfo_screenwidth(), owner.winfo_screenheight())


def position_popup_in_work_area(widget, owner, area):
    """Place the complete native frame, not just its client content."""
    widget.update_idletasks()
    backend = WindowsWindowPlacement(widget) if os.name == 'nt' else None
    state = backend.snapshot() if backend is not None else None
    width = state[0][2]-state[0][0] if state else widget.winfo_width()
    height = state[0][3]-state[0][1] if state else widget.winfo_height()
    x = max(area[0]+8, min(owner.winfo_rootx()+30, area[2]-width-8))
    y = max(area[1]+8, min(owner.winfo_rooty()+30, area[3]-height-8))
    if state:
        backend.move((x, y, width, height))
    else:
        widget.geometry(f'{x:+d}{y:+d}')


def visible_window_target(rect, work_areas, frame_margin=8):
    """Return a centered (x, y, width, height), or None if the title is reachable.

    Work areas are individual monitors, primary first, not the virtual desktop's
    bounding box (which can contain gaps). Coordinates may be negative.
    """
    left, top, right, bottom = rect
    width, height = right-left, bottom-top
    if width <= 0 or height <= 0 or not work_areas:
        return None
    for x1, y1, x2, y2 in work_areas:
        overlap = min(right, x2)-max(left, x1)
        # Permit the usual invisible resize border and partially offscreen sides,
        # but require a usable strip of the actual title bar, not just file rows.
        if overlap >= min(160, width) and y1-frame_margin <= top <= y2-40:
            return None
    x1, y1, x2, y2 = work_areas[0]
    width, height = min(width, x2-x1), min(height, y2-y1)
    return (x1+(x2-x1-width)//2, y1+(y2-y1-height)//2, width, height)


class WindowsWindowPlacement:
    """Native frame/work-area coordinates share the process's DPI awareness."""
    def __init__(self, widget):
        self.widget = widget
        self.user = ctypes.WinDLL('user32', use_last_error=True)
        self.callback_type = ctypes.WINFUNCTYPE(
            wintypes.BOOL, wintypes.HANDLE, wintypes.HDC,
            ctypes.POINTER(wintypes.RECT), wintypes.LPARAM)
        class MonitorInfo(ctypes.Structure):
            _fields_ = [('cbSize', wintypes.DWORD), ('rcMonitor', wintypes.RECT),
                        ('rcWork', wintypes.RECT), ('dwFlags', wintypes.DWORD)]
        self.info_type = MonitorInfo
        signatures = {
            'GetAncestor': ([wintypes.HWND, wintypes.UINT], wintypes.HWND),
            'GetWindowRect': ([wintypes.HWND, ctypes.POINTER(wintypes.RECT)], wintypes.BOOL),
            'GetMonitorInfoW': ([wintypes.HANDLE, ctypes.POINTER(MonitorInfo)], wintypes.BOOL),
            'EnumDisplayMonitors': ([wintypes.HDC, ctypes.POINTER(wintypes.RECT),
                                    self.callback_type, wintypes.LPARAM], wintypes.BOOL),
            'SetWindowPos': ([wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int,
                              ctypes.c_int, ctypes.c_int, wintypes.UINT], wintypes.BOOL),
            'IsIconic': ([wintypes.HWND], wintypes.BOOL),
            'IsZoomed': ([wintypes.HWND], wintypes.BOOL),
            'ShowWindow': ([wintypes.HWND, ctypes.c_int], wintypes.BOOL),
            'GetAsyncKeyState': ([ctypes.c_int], ctypes.c_short),
            'GetDpiForWindow': ([wintypes.HWND], wintypes.UINT),
            'GetSystemMetricsForDpi': ([ctypes.c_int, wintypes.UINT], ctypes.c_int),
        }
        for name, (args, result) in signatures.items():
            fn = getattr(self.user, name)
            fn.argtypes, fn.restype = args, result

    def handle(self):
        return self.user.GetAncestor(self.widget.winfo_id(), 2)

    def snapshot(self):
        hwnd = self.handle()
        # Never restore a deliberately minimized window or interrupt a mouse drag.
        if not hwnd or self.user.IsIconic(hwnd) or self.user.GetAsyncKeyState(1) & 0x8000:
            return None
        rect = wintypes.RECT()
        if not self.user.GetWindowRect(hwnd, ctypes.byref(rect)):
            return None
        areas = []
        @self.callback_type
        def collect(monitor, _dc, _rect, _data):
            info = self.info_type()
            info.cbSize = ctypes.sizeof(info)
            if self.user.GetMonitorInfoW(monitor, ctypes.byref(info)):
                r = info.rcWork
                if r.right > r.left and r.bottom > r.top:
                    areas.append((not bool(info.dwFlags & 1), (r.left, r.top, r.right, r.bottom)))
            return True
        if not self.user.EnumDisplayMonitors(None, None, collect, 0):
            return None
        areas.sort(key=lambda item: item[0])
        dpi = self.user.GetDpiForWindow(hwnd) or 96
        border = (self.user.GetSystemMetricsForDpi(33, dpi) +
                  self.user.GetSystemMetricsForDpi(92, dpi))  # CYSIZEFRAME + CXPADDEDBORDER
        return ((rect.left, rect.top, rect.right, rect.bottom),
                tuple(area for _, area in areas), max(8, border))

    def move(self, target):
        hwnd = self.handle()
        if self.user.IsZoomed(hwnd):
            self.user.ShowWindow(hwnd, 9)  # Restore only an unreachable maximized window.
        # Absolute signed coordinates, no activation or z-order change. Tk's '-x'
        # geometry syntax instead means distance from the RIGHT edge of a screen.
        self.user.SetWindowPos(hwnd, None, *target, 0x0014)  # NOZORDER | NOACTIVATE


class WindowVisibilityGuard:
    """Lightweight Tk-thread check at startup, after undocking, and after resume."""
    def __init__(self, widget, backend=None):
        self.widget = widget
        self.backend = backend if backend is not None else (
            WindowsWindowPlacement(widget) if os.name == 'nt' else None)
        self.previous = None
        self.job = widget.after(250, self._tick)
        widget.bind('<Destroy>', self._destroyed, add='+')

    def _destroyed(self, event):
        if event.widget == self.widget:
            self.close()

    def close(self):
        if self.job is not None:
            self.widget.after_cancel(self.job)
            self.job = None

    def check(self):
        if self.widget.state() in ('withdrawn', 'iconic') or not self.widget.winfo_ismapped():
            self.previous = None
            return
        if self.backend is not None:
            snapshot = self.backend.snapshot()
        else:
            x, y = self.widget.winfo_rootx(), self.widget.winfo_rooty()
            snapshot = ((x, y, x+self.widget.winfo_width(), y+self.widget.winfo_height()),
                        ((0, 0, self.widget.winfo_screenwidth(), self.widget.winfo_screenheight()),))
        # Wait for two stable observations, so changing display/DPI configurations
        # and normal window moves can settle before we intervene.
        if snapshot is not None and snapshot == self.previous:
            target = visible_window_target(*snapshot)
            if target is not None:
                if self.backend is not None:
                    self.backend.move(target)
                else:
                    x, y, width, height = target
                    self.widget.geometry(f'{width}x{height}+{x}+{y}')
                self.previous = None
                return
        self.previous = snapshot

    def _tick(self):
        self.job = None
        try:
            self.check()
        except (tk.TclError, OSError):
            # Display APIs can temporarily fail while Windows switches displays.
            self.previous = None
        if self.widget.winfo_exists():
            self.job = self.widget.after(1000, self._tick)


