"""Categorized, draft-first preferences. No filesystem scanning or network preview."""
import os
import math
from pathlib import Path
import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk, filedialog, messagebox
from datetime import datetime
from functools import lru_cache











SETTINGS_CATEGORIES = (
    ('appearance', 'Appearance'), ('layout', 'Layout & Tabs'),
    ('columns', 'File Columns'), ('navigation', 'Paths & Operations'),
    ('preview', 'Preview'), ('general', 'General'),
)


@lru_cache(maxsize=48)
def settings_check_icon_png(size, selected, disabled, dark):
    """A crisp tick (never the Clam theme's X), independent of installed fonts."""
    supersample=4;extent=size*supersample;unit=extent/20
    pixels=bytearray(extent*extent*4)
    if disabled:
        edge,face,ink=('#657380','#394550','#a3afba') if dark else ('#aeb8c2','#e2e6ea','#657380')
    elif selected:
        edge,face,ink=('#8bc8ff','#8bc8ff','#153449') if dark else ('#176fbc','#176fbc','#ffffff')
    else:
        edge,face,ink=('#a9bbc9','#252d35','#ffffff') if dark else ('#5b6c7b','#ffffff','#153449')
    edge,face,ink=map(_hex_rgba,(edge,face,ink))
    def rounded(x,y,lo,hi,r):
        cx=max(lo+r,min(x,hi-r));cy=max(lo+r,min(y,hi-r))
        return (x-cx)**2+(y-cy)**2<=r*r
    for y in range(extent):
        py=(y+.5)/unit
        for x in range(extent):
            px=(x+.5)/unit
            if not rounded(px,py,1,19,2.3):continue
            color=face if rounded(px,py,2.2,17.8,1.2) else edge
            if selected and min(_distance_to_segment(px,py,5,10,8.5,13.5),
                                _distance_to_segment(px,py,8.5,13.5,15,6.5))<=1.15:
                color=ink
            start=(y*extent+x)*4;pixels[start:start+4]=bytes(color)
    return _rgba_png_downsample(pixels,size,supersample)


def readable_check_style(owner, font, dark=False, prefix='Prefs'):
    """Shared scalable tick indicators, owned by the Tk root across dialogs."""
    return _readable_choice_style(owner, font, dark, prefix, 'Checkbutton')


@lru_cache(maxsize=48)
def settings_radio_icon_png(size, selected, disabled, dark):
    """Round radio indicator with a distinct dot, at the text's reading scale."""
    supersample = 4; extent = size * supersample; unit = extent / 20
    pixels = bytearray(extent * extent * 4)
    edge, face, ink = (('#657380', '#394550', '#a3afba') if dark else
                       ('#aeb8c2', '#e2e6ea', '#657380')) if disabled else (
                      ('#a9bbc9', '#252d35', '#8bc8ff') if dark else
                      ('#5b6c7b', '#ffffff', '#176fbc'))
    edge, face, ink = map(_hex_rgba, (edge, face, ink))
    for y in range(extent):
        for x in range(extent):
            distance = math.hypot((x+.5)/unit-10, (y+.5)/unit-10)
            if distance > 9: continue
            color = ink if selected and distance <= 4.5 else face if distance <= 7.8 else edge
            start = (y*extent+x)*4; pixels[start:start+4] = bytes(color)
    return _rgba_png_downsample(pixels, size, supersample)


def _readable_choice_style(owner, font, dark, prefix, kind):
    root = owner._root()
    size = max(18, font.metrics('linespace'))
    style = ttk.Style(owner)
    cache = getattr(root, '_readable_check_images', {})
    root._readable_check_images = cache
    fonts = getattr(root, '_readable_choice_fonts', {})
    root._readable_choice_fonts = fonts
    fonts[prefix, kind] = font
    key = (prefix, size, dark) if kind == 'Checkbutton' else (prefix, kind, size, dark)
    render = settings_check_icon_png if kind == 'Checkbutton' else settings_radio_icon_png
    if key not in cache:
        cache[key] = {state: tk.PhotoImage(master=root,
            data=render(size, *state, dark), format='png')
            for state in ((False, False), (True, False), (False, True), (True, True))}
    images = cache[key]
    name = f'PFC.{prefix}.{kind}.{size}.{int(dark)}.indicator'
    gap = max(4, round(size*.3))
    if name not in style.element_names():
        style.element_create(name, 'image', images[False, False],
            ('disabled', 'selected', images[True, True]),
            ('disabled', '!selected', images[False, True]),
            ('selected', images[True, False]), width=size+gap, sticky='w')
    layouts = getattr(root, '_readable_choice_layouts', {})
    root._readable_choice_layouts = layouts
    layouts.setdefault(kind, style.layout('T'+kind))
    def replace(layout):
        return [(name if element.endswith('.indicator') else element,
                 {key: replace(value) if key == 'children' else value
                  for key, value in options.items()}) for element, options in layout]
    target = (prefix+'.' if prefix else '')+'T'+kind
    style.layout(target, replace(layouts[kind]))
    style.configure(target, font=font, padding=(max(2, size//10), max(3, size//8)), indicatorsize=size)
    return target


def refresh_control_styles(owner, dark=False):
    """Refresh both existing and newly opened dialogs when interface zoom changes."""
    root = owner._root(); base = tkfont.nametofont('TkDefaultFont', root=root)
    for role, font in getattr(root, '_workflow_fonts', {}).items():
        font.configure(**font_snapshot(base, weight='bold' if role == 'heading' else 'normal'))
    chrome = getattr(root, '_compare_chrome_font', None)
    if chrome is not None: chrome.configure(**font_snapshot(base))
    _readable_choice_style(root, base, dark, '', 'Checkbutton')
    _readable_choice_style(root, base, dark, '', 'Radiobutton')
    for (prefix, kind), font in list(root._readable_choice_fonts.items()):
        _readable_choice_style(root, font, dark, prefix, kind)
    line = base.metrics('linespace'); padding = max(2, round(line*.12))
    style = ttk.Style(root)
    style.configure('PFCWorkflow.Treeview', rowheight=line+8)
    for kind in ('TButton', 'TMenubutton', 'TSpinbox', 'TCombobox', 'TEntry'):
        style.configure(kind, font=base, padding=padding, arrowsize=max(10, round(line*.6)))
    style.configure('TScrollbar', arrowsize=max(12, round(line*.65)))
    root.option_add('*Menu.font', 'TkMenuFont')
    root.option_add('*TCombobox*Listbox.font', 'TkTextFont')


def preference_specs(app):
    """key, category, group, label, choices (None = check), apply method."""
    return [
        ('color_scheme', 'appearance', 'Color Scheme', 'Color Scheme',
         [('light', 'Light'), ('light_grey', 'Light Grey'), ('dark', 'Dark')], 'apply_color_scheme'),
        ('auto_font_size', 'appearance', 'Font Size', 'Auto Font Size', None, 'set_auto_font_size'),
        ('font_size', 'appearance', 'Font Size', 'Font Size',
         [(k, f'{round(v*100)}%') for k, v in app._font_scales.items()], 'apply_font_size'),
        ('panel_count', 'layout', 'Panel Counts', 'Panel Counts',
         [(1, '1 Panel')] + [(n, tr('{count} Panels', count=n)) for n in range(2,5)], 'apply_panel_count'),
        ('tab_style', 'layout', 'Tab Style', 'Tab Style', list(TAB_STYLES.items()), 'apply_tab_style'),
        ('show_hidden', 'columns', 'Name · current tab', 'Show Hidden', None, 'set_hidden_visibility'),
        ('show_system', 'columns', 'Name · current tab', 'Show System', None, 'set_system_visibility'),
        ('show_extensions', 'columns', 'Name · current tab', 'Show File Extension', None, 'set_extension_visibility'),
        ('mix_sorting', 'columns', 'Name · all tabs', 'File/Folder Mix Sorting', None, 'set_mix_sorting'),
        ('long_name_scrolling', 'columns', 'Name · all tabs', 'Long Filename Scrolling', None, 'set_long_name_scrolling'),
        ('onedrive_overlay', 'columns', 'Status icons', 'OneDrive Sync Overlay', None, 'apply_column_settings'),
        ('vcs_overlay', 'columns', 'Status icons', 'Git / SVN Overlay', None, 'set_vcs_overlay'),
        ('column_ext', 'columns', 'Ext', 'Show Ext column', None, 'apply_column_settings'),
        ('column_size', 'columns', 'Size', 'Show Size column', None, 'apply_column_settings'),
        ('size_emphasis', 'columns', 'Size', 'Emphasize GB / TB', None, 'apply_column_settings'),
        ('column_modified', 'columns', 'Date Modified', 'Show Date Modified column', None, 'apply_column_settings'),
        ('date_order', 'columns', 'Date Modified', 'Date format', [('ymd','YYYY/MM/DD'), ('mdy','MM/DD/YYYY')], 'apply_column_settings'),
        ('time_style', 'columns', 'Date Modified', 'Time format',
         [('24','24-hour (hh:mm)'), ('12','12-hour (1136a / 0515p)'), ('none','Date only')], 'apply_column_settings'),
        ('right_click_menu', 'navigation', 'Right Click Menu', 'Right Click Menu',
         [('explorer','File Explorer'), ('pfc','PFC')], 'save_config'),
        ('recycle_bin', 'navigation', 'File Operation Settings', 'Send Delete to Recycle Bin', None, 'save_config'),
        ('continue_errors', 'navigation', 'File Operation Settings', 'Continue After File Errors', None, 'save_config'),
        ('extension_effect', 'preview', 'F3 Preview', 'Syntax colors & Markdown (Extension Effect)', None, 'set_extension_effect'),
        ('ui_language', 'general', 'UI Language', 'UI Language', list(LANGUAGES), 'apply_ui_language'),
        ('auto_start', 'general', 'Windows startup', 'Auto Start when boot', None, 'toggle_auto_start'),
    ]


class SettingsDialog(tk.Toplevel):
    def __init__(self, app, category='appearance'):
        super().__init__(app)
        self.withdraw()
        self.app = app
        self.pane = app.active
        self.title(tr('PFC Settings'))
        self.transient(app)
        # Snapshot the actual interface font, including automatic scaling.
        # Draft changes do not move controls until Apply; never shrink reading text.
        base = tkfont.nametofont('TkDefaultFont')
        self.font = tkfont.Font(self, **font_snapshot(base))
        self.heading_font = tkfont.Font(self, **dict(self.font.actual(), size=self.font.cget('size'), weight='bold'))
        self.small_font = tkfont.Font(self, **dict(self.font.actual(), size=self.font.cget('size')))
        self.specs = preference_specs(app)
        self.vars, self.original = {}, {}
        for key, _cat, _group, _label, choices, _method in self.specs:
            value = self._read(key)
            self.original[key] = value
            cls = tk.BooleanVar if choices is None else tk.IntVar if isinstance(value,int) else tk.StringVar
            self.vars[key] = cls(self, value=value)
            self.vars[key].trace_add('write', self._changed)
        self.prefix_original = [dict(item) for item in app.custom_home_prefixes]
        self.prefix_draft = [dict(item) for item in self.prefix_original]
        self.category = category if category in dict(SETTINGS_CATEGORIES) else 'appearance'
        self.controls = {}
        self.images = []
        self.status_var = tk.StringVar(self)
        self._shot_sources = {}
        self._shot_job = None
        self._page_top_job = None
        self._preview_expanded = set()
        self._build()
        self._work_area = area = popup_work_area(app)
        sw, sh = area[2]-area[0], area[3]-area[1]
        ratio=max(1,self.font.metrics('linespace')/20)
        width, height = min(round(1180*ratio), sw-48), min(round(720*ratio), sh-80)
        self.geometry(f'{width}x{height}')
        self.minsize(min(720,width), min(560,height))
        self.protocol('WM_DELETE_WINDOW', self.cancel)
        self.bind('<Escape>', lambda _e: self.cancel())
        # Stop application-wide file shortcuts from acting behind the modal dialog.
        self.bind('<KeyPress>', self._key_event, add='+')
        self.bind('<Control-Return>', lambda _e: self.apply(close=True))
        self.bind('<Control-MouseWheel>', lambda _e: 'break')
        self.bind('<Control-Button-4>', lambda _e: 'break')
        self.bind('<Control-Button-5>', lambda _e: 'break')
        self.bind('<MouseWheel>', self._wheel)
        self.bind('<Button-4>', lambda _e: self._scroll(-3))
        self.bind('<Button-5>', lambda _e: self._scroll(3))
        self.bind('<FocusIn>', self._reveal_focus, add='+')
        self.deiconify()
        position_popup_in_work_area(self, app, self._work_area)
        self.grab_set()
        self.nav.focus_set()

    def _read(self, key):
        if key in ('show_hidden','show_system','show_extensions'):
            return getattr(self.pane, key)
        if key.startswith('column_'):
            return self.app.column_visible_vars[key[7:]].get()
        return getattr(self.app, key+'_var').get()

    def _build(self):
        p = self.app.palette
        self.configure(bg=p['window'])
        style = ttk.Style(self)
        for suffix in ('TButton','TCheckbutton','TLabel','TCombobox','TEntry'):
            style.configure('Prefs.'+suffix, font=self.font)
        self._checkbutton_style(style)
        style.configure('PrefsTitle.TLabel', font=self.heading_font)
        self.footer = ttk.Frame(self, padding=12)
        self.footer.pack(side='bottom', fill='x')
        ttk.Button(self.footer, text=tr('OK'), style='Prefs.TButton', width=9,
                   command=lambda:self.apply(close=True)).pack(side='right')
        ttk.Button(self.footer, text=tr('Cancel'), style='Prefs.TButton', width=9,
                   command=self.cancel).pack(side='right', padx=6)
        self.apply_button = ttk.Button(self.footer, text=tr('Apply'), style='Prefs.TButton', width=9, command=self.apply)
        self.apply_button.pack(side='right')
        self.status_label = ttk.Label(self.footer, textvariable=self.status_var, style='Prefs.TLabel')
        self.status_label.pack(side='left', fill='x', expand=True)
        body = ttk.Frame(self, padding=(12,12,12,0)); body.pack(fill='both', expand=True)
        self.nav = tk.Listbox(body, font=self.font, width=18, exportselection=False,
                              activestyle='none', relief='flat', borderwidth=0,
                              highlightthickness=1, background=p['surface_alt'], foreground=p['text'],
                              selectbackground=p['selection'], selectforeground='#ffffff',
                              selectmode='browse')
        self.nav.pack(side='left', fill='y', padx=(0,14))
        self.compact_nav = ttk.Combobox(body, state='readonly', font=self.font,
            style='Prefs.TCombobox', values=[tr(label) for _,label in SETTINGS_CATEGORIES], width=1)
        self.compact_nav.bind('<<ComboboxSelected>>', lambda _e:
            self.show_page(SETTINGS_CATEGORIES[self.compact_nav.current()][0]))
        self._compact_navigation = False
        body.bind('<Configure>', self._layout_navigation)
        for _key, label in SETTINGS_CATEGORIES: self.nav.insert('end', tr(label))
        self.nav.bind('<<ListboxSelect>>', self._select)
        right = self.content_area = ttk.Frame(body); right.pack(fill='both', expand=True)
        title_bar=ttk.Frame(right);title_bar.pack(fill='x',pady=(0,6))
        self.title_label = ttk.Label(title_bar, style='PrefsTitle.TLabel'); self.title_label.pack(side='left')
        self.preview_toggle=ttk.Button(title_bar,style='Prefs.TButton',width=0,command=self.toggle_preview)
        # At large reading scales let preview + controls scroll together. A fixed
        # preview must never consume the whole viewport and hide every setting.
        self._whole_page_scroll = True
        if not self._whole_page_scroll:
            self.comparison = ttk.Frame(right)
            self.comparison.pack(fill='x', pady=(0,8))
        content = ttk.Frame(right); content.pack(fill='both', expand=True)
        self.canvas = tk.Canvas(content, highlightthickness=0, bg=p['window'])
        self.scrollbar = ttk.Scrollbar(content, orient='vertical', command=self.canvas.yview)
        self.scrollbar.pack(side='right', fill='y'); self.canvas.pack(fill='both', expand=True)
        self.canvas.configure(yscrollcommand=self.scrollbar.set)
        self.sheet = ttk.Frame(self.canvas)
        self.page_id = self.canvas.create_window(0,0,window=self.sheet,anchor='nw')
        if self._whole_page_scroll:
            self.comparison = ttk.Frame(self.sheet)
            self.comparison.pack(fill='x', pady=(0,8))
        self.intro = ttk.Label(self.sheet, text=tr('Changes take effect only after Apply or OK.'), style='Prefs.TLabel', wraplength=500)
        self.intro.pack(fill='x', pady=(0,8))
        self.comparison.bind('<Configure>', lambda _e:self._schedule_shots())
        self.page = ttk.Frame(self.sheet, padding=(2,0,12,10))
        self.page.pack(fill='x')
        self.sheet.bind('<Configure>', lambda _e:self._scroll_region())
        self.canvas.bind('<Configure>', self._resize)
        index = [key for key,_label in SETTINGS_CATEGORIES].index(self.category)
        self.nav.selection_set(index); self.nav.activate(index)
        self.show_page(self.category)

    def _layout_navigation(self, event):
        if event.widget is not self.nav.master: return
        longest = max(self.font.measure(tr(label)) for _,label in SETTINGS_CATEGORIES)
        compact = longest > event.width*.26
        if compact != self._compact_navigation:
            self._compact_navigation = compact
            if compact:
                self.nav.pack_forget()
                self.compact_nav.pack(side='top', fill='x', pady=(0,8), before=self.content_area)
            else:
                self.compact_nav.pack_forget()
                self.nav.pack(side='left', fill='y', padx=(0,14), before=self.content_area)
        if not compact:
            self.nav.configure(width=max(8,min(24,round((longest+18)/max(1,self.font.measure('0'))))))

    def _checkbutton_style(self, style):
        # Ttk elements retain image names after the dialog closes. Own these four
        # images on the application, reuse them on Apply/reopen, and keep the
        # native checkbutton's focus, mouse and Space-key behavior intact.
        dark=self.app.color_scheme_var.get()=='dark'
        readable_check_style(self, self.font, dark, 'Prefs')

    def _resize(self, event):
        self.canvas.itemconfigure(self.page_id,width=event.width)
        self._scroll_region()
        self.intro.configure(wraplength=max(100,event.width-12))
        for label in getattr(self,'wrap_labels',[]):
            label.configure(wraplength=max(140,event.width-36))
        self._schedule_shots()
        self._layout_cards(event.width)

    def _scroll_region(self):
        bounds = self.canvas.bbox('all')
        if bounds:
            self.canvas.configure(scrollregion=(0, 0, max(bounds[2], self.canvas.winfo_width()),
                                                 max(bounds[3], self.canvas.winfo_height())))

    def apply_scale(self, _scale=None):
        self.font.configure(**font_snapshot(tkfont.nametofont('TkDefaultFont')))
        self.heading_font.configure(**font_snapshot(self.font, weight='bold'))
        self.small_font.configure(**font_snapshot(self.font))
        self._checkbutton_style(ttk.Style(self))
        for sample, _ in self.layout_examples:
            sample.font.configure(**font_snapshot(self.font, size=-max(12, round(abs(self.font.cget('size'))*.85))))
            sample.bold.configure(**font_snapshot(sample.font, weight='bold'))
            sample.line = max(22, sample.font.metrics('linespace')+4)
            sample.canvas.configure(height=7*sample.line); sample._key = None; sample._schedule()
        sample = self.page_preview
        if sample is not None:
            sample.font.configure(**font_snapshot(self.font))
            sample.bold.configure(**font_snapshot(self.font, weight='bold'))
            sample.line = max(23, sample.font.metrics('linespace')+5)
            sample.canvas.configure(height=8*sample.line); sample._key = None; sample._schedule()
        self._schedule_shots()

    def _layout_cards(self, width):
        cards = getattr(self, '_comparison_cards', [])
        # Readable titles and diagrams take precedence over a forced two-column
        # layout. Keep Before first, After second in compact/high-scale windows.
        threshold = max(660, self.heading_font.measure(tr('After Apply · 4 Panels'))*2+64)
        stacked = width < threshold
        for i, card in enumerate(cards):
            card.grid_configure(row=i if stacked else 0, column=0 if stacked else i,
                                columnspan=2 if stacked else 1,
                                padx=(0, 0 if stacked else 8), pady=(0, 8))
        for label, control in getattr(self, '_compact_controls', []):
            narrow = width < label.winfo_reqwidth()+self.font.measure('MMMMMMMMMMMM')+70
            label.pack_configure(side='top' if narrow else 'left', anchor='w')
            control.pack_configure(side='top', fill='x', expand=True)
        bar = getattr(self, '_comparison_bar', None)
        if bar:
            label, button = bar
            narrow = width < label.winfo_reqwidth()+button.winfo_reqwidth()+24
            label.pack_configure(side='top' if narrow else 'left', anchor='w')
            button.pack_configure(side='top' if narrow else 'right', anchor='e')

    def _select(self, _event=None):
        selection=self.nav.curselection()
        if selection:self.show_page(SETTINGS_CATEGORIES[selection[0]][0])

    def toggle_preview(self):
        if self.category not in ('general','navigation'):return
        if self.category in self._preview_expanded:self._preview_expanded.remove(self.category)
        else:self._preview_expanded.add(self.category)
        self._sync_comparison_visibility()
        self._changed()
        if self._page_top_job is not None:self.after_cancel(self._page_top_job)
        self._page_top_job=self.after_idle(self._show_page_top)

    def _sync_comparison_visibility(self):
        optional=self.category in ('general','navigation')
        expanded=not optional or self.category in self._preview_expanded
        if optional:
            self.preview_toggle.configure(text=tr('Hide preview' if expanded else 'Show preview'))
            self.preview_toggle.pack(side='right')
        else:self.preview_toggle.pack_forget()
        if not expanded:
            self.comparison.pack_forget()
            return
        if optional and self.page_preview is None:
            self.page_preview=SettingsSamplePreview(self.comparison,self.category,self.font)
            self.page_preview.pack(fill='x')
        self.comparison.pack(before=self.intro if self._whole_page_scroll else self.canvas.master,
                             fill='x',pady=(0,8))

    def _label(self, parent, text, heading=False):
        label=ttk.Label(parent,text=tr(text),style='PrefsTitle.TLabel' if heading else 'Prefs.TLabel',wraplength=480)
        label.pack(anchor='w',fill='x',pady=(8 if heading else 2,6))
        self.wrap_labels.append(label)
        return label

    def show_page(self, category):
        self.category=category
        index=[key for key,_label in SETTINGS_CATEGORIES].index(category)
        self.compact_nav.current(index)
        if self.nav.curselection()!=(index,):
            self.nav.selection_clear(0,'end');self.nav.selection_set(index);self.nav.activate(index)
        for child in self.page.winfo_children():child.destroy()
        for child in self.comparison.winfo_children():child.destroy()
        self.controls={};self.images=[];self.wrap_labels=[];self.preview_labels=[];self.date_example=None
        self.layout_examples=[];self.sample_title=None;self.danger_note=None;self.page_preview=None
        self._comparison_cards=[];self._compact_controls=[];self._comparison_bar=None
        self.title_label.configure(text=tr(dict(SETTINGS_CATEGORIES)[category]))
        self.canvas.yview_moveto(0)
        notes={
            'appearance':'Preview only — Apply or OK saves changes.',
            'layout':'Compare complete layouts and tab styles before applying.',
            'columns':'Name visibility applies to the tab where Settings was opened. Other column preferences apply to all tabs. Hidden columns can be restored here.',
            'navigation':'Configure file menus, delete behavior and path shortcuts. Changes apply only after Apply or OK.',
            'preview':'Controls F3 Preview only. It does not change files, index drives or enable external plugins.',
            'general':'Choose the interface language and Windows sign-in behavior. Updates remain a manual action in Help.',
        }
        self.intro.configure(text=tr(notes[category]))
        if category in ('appearance','layout'):
            self._previews()
        elif category not in ('general','navigation'):
            self.page_preview=SettingsSamplePreview(self.comparison,category,self.font)
            self.page_preview.pack(fill='x')
        self._sync_comparison_visibility()
        group=None
        for key,cat,title,label,choices,_method in self.specs:
            if cat!=category:continue
            compact=choices is not None
            if title!=group and category not in ('appearance','layout'):
                if group is not None:ttk.Separator(self.page).pack(fill='x',pady=8)
                if not compact or label!=title:self._label(self.page,title,True)
                group=title
            if choices is None:
                container=self.page
                if key in ('auto_font_size','onedrive_overlay'):
                    container=ttk.Frame(self.page);container.pack(fill='x',pady=5)
                if key=='auto_font_size':
                    ttk.Button(container,text=tr('Details…'),style='Prefs.TButton',command=lambda:messagebox.showinfo(
                        tr('Auto Font Size'),tr('Fits up to 30 filenames in Panels 1–2 when enabled or after window width, monitor or manual layout changes. Keeps the scale while browsing folders, tabs and scrolling. Range: 100–300%; Panels 3–4 are ignored.'),parent=self)).pack(side='right',padx=(6,0))
                control=ttk.Checkbutton(container,text=tr(label),variable=self.vars[key],style='Prefs.TCheckbutton')
                control.pack(side='left' if container is not self.page else 'top',anchor='w',pady=0 if container is not self.page else 5)
            else:
                container=self.page
                if compact:
                    container=ttk.Frame(self.page);container.pack(fill='x',pady=(4,6))
                    control_label=ttk.Label(container,text=tr(label),style='PrefsTitle.TLabel')
                    control_label.pack(side='left',padx=(0,8))
                elif label!=title:self._label(self.page,label)
                control=ttk.Combobox(container,state='readonly',style='Prefs.TCombobox',font=self.font,
                                      values=[tr('{count} Panels',count=value) if key=='panel_count' and value>1
                                              else tr(str(label)) for value,label in choices])
                control.current([v for v,_ in choices].index(self.vars[key].get()))
                control.pack(fill='x',expand=compact,pady=(0,0 if compact else 6))
                if compact:self._compact_controls.append((control_label,control))
                self._prepare_combo(control)
                control.bind('<<ComboboxSelected>>',lambda _e,k=key,c=control,opts=choices:self.vars[k].set(opts[c.current()][0]))
            self.controls[key]=control
            if key=='auto_start' and os.name!='nt':
                control.state(['disabled']); self._label(self.page,'Windows only. No system change is made on this platform.')
            hints={
                'auto_font_size':'Auto fits Panels 1–2 (100–300%). Stable while browsing.',
                'onedrive_overlay':'Attached top-right triangle: cyan-blue = local copy in sync; red = sync error; orange = syncing/pending; light violet = online only; yellow = paused; pink = warning. No triangle = unknown. Git/SVN stays top-left; bottom corners are reserved.',
                'size_emphasis':'GB is bold; TB is bold red. This changes display only, not file sizes.',
                'right_click_menu':'File Explorer uses the Windows native file menu. Blank-area and column menus remain PFC shortcuts.',
                'continue_errors':'Continue with the remaining files after a failure; errors are still reported.',
                'extension_effect':'On: syntax colors and formatted Markdown. Off: plain source text. Outline, properties, links and tables are in F3 Preview.',
                'ui_language':'Changes the interface after Apply, not your file names.',
                'auto_start':'Auto Start writes a Windows sign-in entry only when applied. Follow your organization’s software policy. Updates remain a manual action in Help.',
            }
            if key=='onedrive_overlay':
                ttk.Button(container,text=tr('Details…'),style='Prefs.TButton',width=0,
                    command=lambda text=hints[key]:messagebox.showinfo(tr('OneDrive Sync Overlay'),tr(text),parent=self)).pack(side='right',padx=(6,0))
            elif key in hints:self._label(self.page,hints[key])
            if key=='recycle_bin':self.danger_note=self._label(self.page,'')
            if key=='time_style':self.date_example=self._label(self.page,'')
        if category=='navigation':self._prefix_rows()
        for label in self.wrap_labels:
            label.configure(wraplength=max(140,self.canvas.winfo_width()-36))
        self._changed()
        self._layout_cards(self.canvas.winfo_width())
        if self._page_top_job is not None:self.after_cancel(self._page_top_job)
        self._page_top_job=self.after_idle(self._show_page_top)

    def _show_page_top(self):
        # Rebuilding a differently sized page changes the scrollregion after
        # show_page returns. Reset after geometry settles, not against the old
        # page's region (which can strand the preview above the viewport).
        self._page_top_job=None
        self.update_idletasks()
        self.canvas.yview_moveto(0)

    def _previews(self):
        if self.category=='layout':
            return self._layout_previews()
        bar=ttk.Frame(self.comparison);bar.pack(fill='x')
        title=ttk.Label(bar,text=tr('Style comparison'),style='PrefsTitle.TLabel');title.pack(side='left')
        enlarge=ttk.Button(bar,text=tr('Compare at full size…'),style='Prefs.TButton',
                   command=lambda:self._enlarge(None));enlarge.pack(side='right')
        self._comparison_bar=(title,enlarge)
        caption=ttk.Label(self.comparison,text=tr('Sample style at 100%; text size shown below.' if self.category=='appearance'
                          else 'Sample tabs and file list; panel layout is shown below.'),
                          style='Prefs.TLabel',wraplength=480)
        caption.pack(fill='x',pady=(2,4));self.comparison_caption=caption
        cards=ttk.Frame(self.comparison);cards.pack(fill='x')
        cards.columnconfigure((0,1),weight=1,uniform='preview')
        for i,(title,values) in enumerate((('Current style',self.original),('After Apply',None))):
            card=ttk.Frame(cards);card.grid(row=0,column=i,sticky='nsew',padx=(0,8))
            self._comparison_cards.append(card)
            ttk.Label(card,text=tr(title),style='PrefsTitle.TLabel').pack(anchor='w',pady=(2,4))
            label=tk.Label(card,bd=1,relief='solid',anchor='center',bg=self.app.palette['surface'],cursor='hand2')
            label.pack(fill='x',pady=(0,8))
            label.bind('<Button-1>',lambda _e:self._enlarge(None))
            self.preview_labels.append((label,values))
        if self.category=='appearance':
            self.sample_title=ttk.Label(self.comparison,style='PrefsTitle.TLabel')
            self.sample_title.pack(anchor='w',pady=(0,3))
            self.sample_font=tkfont.Font(self)
            # Reserve the maximum sample height: choosing 100–300% cannot move
            # the controls under the pointer or push the comparison off-screen.
            self.sample_font.configure(size=-round(self._sample_pixels()*3))
            self.sample_box_height=self.sample_font.metrics('linespace')+4
            holder=ttk.Frame(self.comparison,height=self.sample_box_height)
            holder.pack(fill='x');holder.pack_propagate(False)
            self.font_example=tk.Label(holder,text='Notes.md · Aa 123',anchor='w',
                bg=self.app.palette['surface'],fg=self.app.palette['text'],font=self.sample_font)
            self.font_example.pack(fill='both',expand=True)

    def _layout_previews(self):
        bar=ttk.Frame(self.comparison);bar.pack(fill='x')
        title=ttk.Label(bar,text=tr('Panel layout comparison'),style='PrefsTitle.TLabel');title.pack(side='left')
        enlarge=ttk.Button(bar,text=tr('Enlarge comparison…'),style='Prefs.TButton',
                   command=lambda:self._enlarge(None));enlarge.pack(side='right')
        self._comparison_bar=(title,enlarge)
        self.comparison_caption=ttk.Label(self.comparison,
            text=tr('Whole-window illustration. The left stays unchanged until Apply; the right follows your choices.'),
            style='Prefs.TLabel',wraplength=480)
        self.comparison_caption.pack(fill='x',pady=(2,4))
        cards=ttk.Frame(self.comparison);cards.pack(fill='x')
        cards.columnconfigure((0,1),weight=1,uniform='layout-preview')
        for i,values in enumerate((self.original,None)):
            sample=SettingsLayoutPreview(cards,self.font,before=i==0)
            sample.grid(row=0,column=i,sticky='nsew',padx=(0,8))
            self._comparison_cards.append(sample)
            self.layout_examples.append((sample,values))

    def _enlarge(self,values):
        layout=self.category=='layout'
        popup=tk.Toplevel(self);popup.transient(self);popup.title(tr('Panel layout comparison' if layout else 'Style comparison'))
        sw,sh=self.winfo_screenwidth(),self.winfo_screenheight()
        wide=sw>=1180
        width,height=min(sw-48,1140 if wide else 620),min(sh-80,(410 if wide else 720) if layout else (330 if wide else 600))
        popup.geometry(f'{width}x{height}+{max(0,(sw-width)//2)}+{max(0,(sh-height)//2)}')
        footer=ttk.Frame(popup);footer.pack(side='bottom',fill='x',pady=8)
        canvas=tk.Canvas(popup,highlightthickness=0,bg=self.app.palette['window'])
        vertical=ttk.Scrollbar(popup,command=canvas.yview);vertical.pack(side='right',fill='y')
        horizontal=ttk.Scrollbar(popup,orient='horizontal',command=canvas.xview);horizontal.pack(side='bottom',fill='x')
        canvas.pack(fill='both',expand=True)
        canvas.configure(yscrollcommand=vertical.set,xscrollcommand=horizontal.set)
        body=ttk.Frame(canvas,padding=10);canvas.create_window(0,0,window=body,anchor='nw')
        for i,(title,state) in enumerate((('Current style',self.original),('After Apply',values or {k:v.get() for k,v in self.vars.items()}))):
            card=ttk.Frame(body);card.grid(row=0 if wide else i,column=i if wide else 0,padx=6,pady=4)
            if layout:
                sample=SettingsLayoutPreview(card,self.font,before=i==0,height=220)
                sample.canvas.configure(width=540)
                sample.pack();sample.update_sample(state)
                continue
            ttk.Label(card,text=tr(title),style='PrefsTitle.TLabel').pack(anchor='w',pady=(0,6))
            shot=tk.PhotoImage(master=popup,data=SETTINGS_SHOTS[state['color_scheme']+'/'+state['tab_style']],format='png')
            label=ttk.Label(card,image=shot);label.image=shot;label.pack()
        body.bind('<Configure>',lambda _e:canvas.configure(scrollregion=canvas.bbox('all')))
        popup.bind('<MouseWheel>',lambda e:(canvas.yview_scroll(-1 if e.delta>0 else 1,'units'),'break')[-1])
        popup.bind('<Button-4>',lambda _e:(canvas.yview_scroll(-3,'units'),'break')[-1])
        popup.bind('<Button-5>',lambda _e:(canvas.yview_scroll(3,'units'),'break')[-1])
        def close():
            popup.grab_release();popup.destroy();self.grab_set();self.nav.focus_set()
        button=ttk.Button(footer,text=tr('Close'),command=close,style='Prefs.TButton')
        button.pack()
        popup.protocol('WM_DELETE_WINDOW',close);popup.bind('<Escape>',lambda _e:close())
        popup.bind('<KeyPress>',self._key_event,add='+')
        popup.grab_set()
        popup.update_idletasks();button.focus_force()

    def _schedule_shots(self):
        if self._shot_job is None:self._shot_job=self.after_idle(self._update_shots)

    def _update_shots(self):
        if self._shot_job is not None:self.after_cancel(self._shot_job);self._shot_job=None
        width=max(120,(self.comparison.winfo_width()-26)//2)
        # Crop the relevant tab/path/list detail, then resize with smaller steps
        # than integer subsampling. Original full screenshots remain in Compare.
        factor=max(4,math.ceil(360*4/min(360,width)))
        if getattr(self,'comparison_caption',None) is not None and self.comparison_caption.winfo_exists():
            self.comparison_caption.configure(wraplength=max(100,self.comparison.winfo_width()-12))
        if self.sample_title is not None:
            self.sample_title.configure(wraplength=max(100,self.comparison.winfo_width()-12))
        for label,values in getattr(self,'preview_labels',[]):
            values=values or {key:var.get() for key,var in self.vars.items()}
            key=values['color_scheme']+'/'+values['tab_style']
            if getattr(label,'shot_key',None)!=(key,factor):
                if key not in self._shot_sources:
                    photo=tk.PhotoImage(master=self,data=SETTINGS_SHOTS[key],format='png')
                    detail=tk.PhotoImage(master=self)
                    detail.tk.call(str(detail),'copy',str(photo),'-from',0,0,360,150)
                    self._shot_sources[key]=detail
                photo=self._shot_sources[key]
                label.image=photo if factor==4 else photo.zoom(4).subsample(factor)
                label.configure(image=label.image);label.shot_key=(key,factor)

    def _layout_preview(self):
        for sample,values in self.layout_examples:
            values=values or {key:var.get() for key,var in self.vars.items()}
            sample.update_sample(values)

    def _sample_pixels(self):
        base=self.app._base_font_sizes['TkDefaultFont']
        return abs(base)*(1 if base<0 else self.app._base_tk_scaling)

    def _prepare_combo(self, control):
        popdown=self.tk.call('ttk::combobox::PopdownWindow',str(control))
        self.tk.call(str(popdown)+'.f.l','configure','-font',str(self.font))
        # A wheel gesture over a closed combo scrolls without changing a draft.
        control.bind('<MouseWheel>',self._wheel)
        control.bind('<Button-4>',lambda _e:self._scroll(-3))
        control.bind('<Button-5>',lambda _e:self._scroll(3))

    def _prefix_rows(self):
        self._label(self.page,'Custom folder prefixes',True)
        self._label(self.page,'Choose up to three prefixes. Empty paths disable a slot.')
        self.prefix_rows=[]
        for index,item in enumerate(self.prefix_draft):
            row=ttk.Frame(self.page);row.pack(fill='x',pady=5)
            keys=list(PREFIX_ICONS)
            icon=ttk.Combobox(row,values=[tr(PREFIX_ICONS[k]) for k in keys],state='readonly',font=self.font,style='Prefs.TCombobox',width=12)
            self._prepare_combo(icon)
            icon.current(keys.index(item['icon']));icon.pack(side='left')
            icon_size=max(16,self.font.metrics('linespace'))
            img=prefix_icon(self,item['icon'],icon_size);self.images.append(img)
            picture=ttk.Label(row,image=img);picture.pack(side='left',padx=4)
            path=tk.StringVar(self,value=item['path'])
            entry=ttk.Entry(self.page,textvariable=path,font=self.font);entry.pack(fill='x',pady=(0,5))
            def update(_e=None,i=index,c=icon,v=path,p=picture,size=icon_size):
                self.prefix_draft[i]={'icon':keys[c.current()],'path':v.get()}
                if getattr(p,'icon_key',None)!=keys[c.current()]:
                    p.image=prefix_icon(self,keys[c.current()],size);p.configure(image=p.image)
                    p.icon_key=keys[c.current()]
                self._changed()
            icon.bind('<<ComboboxSelected>>',update)
            path.trace_add('write',lambda *_args,fn=update:fn())
            def browse(v=path):
                selected=filedialog.askdirectory(parent=self)
                if selected:v.set(selected)
            ttk.Button(row,text=tr('Browse…'),command=browse,style='Prefs.TButton').pack(side='right')
            self.prefix_rows.append((icon,path,entry))

    def _changed(self,*_args):
        if not hasattr(self,'apply_button'):return
        dirty=any(var.get()!=self.original[key] for key,var in self.vars.items()) or self.prefix_draft!=self.prefix_original
        self.apply_button.state(['!disabled'] if dirty else ['disabled'])
        self.status_var.set(tr('Unsaved changes') if dirty else tr('No pending changes'))
        for key,_cat,_group,_label,choices,_method in self.specs:
            if choices is not None and key in self.controls:
                self.controls[key].current([value for value,_label in choices].index(self.vars[key].get()))
        if 'font_size' in self.controls:
            self.controls['font_size'].configure(state='disabled' if self.vars['auto_font_size'].get() else 'readonly')
        self._update_shots()
        if self.page_preview is not None:
            self.page_preview.update_sample({k:v.get() for k,v in self.vars.items()},self.prefix_draft)
        if self.category=='appearance' and hasattr(self,'font_example') and self.font_example.winfo_exists():
            scale=self.app._font_scales[self.vars['font_size'].get()]
            self.sample_font.configure(family=self.font.actual('family'),size=-round(self._sample_pixels()*scale))
            title='File text after Apply · {percent}%' if not self.vars['auto_font_size'].get() else 'Auto font · {percent}% reference; follows window width'
            self.sample_title.configure(text=tr(title,percent=round(scale*100)))
            p=color_scheme(self.vars['color_scheme'].get())
            self.font_example.configure(bg=p['surface'],fg=p['text'])
        if self.category=='layout':self._layout_preview()
        if self.category=='columns' and self.date_example is not None:
            stamp=datetime(2026,9,22,17,15).timestamp()
            shown=self.vars['column_modified'].get()
            self.date_example.configure(text=tr('Example')+': '+modified_text(stamp,self.vars['date_order'].get(),self.vars['time_style'].get()) if shown else tr('Date column hidden; format is remembered.'))
            for key in ('date_order','time_style'):self.controls[key].configure(state='readonly' if shown else 'disabled')
            self.controls['size_emphasis'].state(['!disabled'] if self.vars['column_size'].get() else ['disabled'])
        if self.danger_note is not None:
            self.danger_note.configure(text=tr('Delete moves items to Recycle Bin. Shift+Delete is always permanent.') if self.vars['recycle_bin'].get() else tr('Warning: Delete will permanently remove files after Apply.'))
            self.danger_note.configure(foreground=self.app.palette['text'] if self.vars['recycle_bin'].get() else
                                      '#ffb4a9' if self.app.color_scheme_var.get()=='dark' else '#b00020')

    def apply(self,close=False):
        prefixes=[]
        for item in self.prefix_draft:
            value=item['path'].strip().strip('"')
            if value:
                path=Path(os.path.normpath(os.path.expandvars(value))).expanduser()
                if not path.is_absolute():
                    messagebox.showerror(tr('Custom folder prefixes'),tr('Enter an absolute folder path.'),parent=self)
                    self.nav.selection_clear(0,'end');self.nav.selection_set(3);self.show_page('navigation')
                    return
                value=str(path)
            prefixes.append({'icon':item['icon'],'path':value})
        changed=[s for s in self.specs if self.vars[s[0]].get()!=self.original[s[0]]]
        # Visibility is explicitly scoped to the original tab, before layout switches.
        for key,_cat,_group,_label,_choices,_method in changed:
            value=self.vars[key].get()
            if key.startswith('column_'):self.app.column_visible_vars[key[7:]].set(value)
            else:getattr(self.app,key+'_var').set(value)
        methods=[]
        for key,_cat,_group,_label,_choices,method in changed:
            if key in ('show_hidden','show_system','show_extensions'):
                setattr(self.pane,key,self.vars[key].get())
                if 'pane_refresh' not in methods:methods.append('pane_refresh')
            elif method not in methods:methods.append(method)
        # Language replaces menus; apply it last and rebuild this dialog's labels.
        if 'apply_ui_language' in methods:methods.remove('apply_ui_language');methods.append('apply_ui_language')
        try:
            for method in methods:
                if method=='pane_refresh':self.pane.refresh();self.pane.on_change()
                elif method=='apply_ui_language':self.app._apply_ui_language_now()
                else:getattr(self.app,method)()
            if self.app.auto_font_size_var.get() and any(method in methods for method in
                    ('set_auto_font_size','apply_font_size','apply_panel_count')):
                # Establish the actual auto-selected scale before taking the new
                # baseline, instead of showing a stale disabled percentage.
                if self.app._auto_font_job is not None:
                    self.app.after_cancel(self.app._auto_font_job)
                    self.app._auto_font_job=None
                self.app._apply_automatic_font_size(allow_settings=True)
            if prefixes!=self.prefix_original:self.app.set_home_prefixes(prefixes)
            self.app.save_config()
        except Exception as exc:
            messagebox.showerror(tr('PFC Settings'),tr('Some settings may already be applied. Review the settings before retrying.')+'\n\n'+str(exc),parent=self)
            return
        for key in self.vars:self.original[key]=self._read(key);self.vars[key].set(self.original[key])
        self.prefix_original=[dict(item) for item in prefixes];self.prefix_draft=[dict(item) for item in prefixes]
        if close:self.cancel();return
        self.font.configure(**font_snapshot(tkfont.nametofont('TkDefaultFont')))
        self.heading_font.configure(**font_snapshot(self.font,weight='bold'))
        self.small_font.configure(**font_snapshot(self.font))
        for child in self.winfo_children():child.destroy()
        self.title(tr('PFC Settings'));self._build();self.nav.focus_set()

    def cancel(self):
        if self._shot_job is not None:self.after_cancel(self._shot_job);self._shot_job=None
        if self._page_top_job is not None:self.after_cancel(self._page_top_job);self._page_top_job=None
        self.grab_release();self.destroy()
        self.app._schedule_auto_font_size()

    def _key_event(self,event):
        if event.keysym in ('Tab','ISO_Left_Tab'):
            previous=event.keysym=='ISO_Left_Tab' or bool(event.state & 1)
            target=event.widget.tk_focusPrev() if previous else event.widget.tk_focusNext()
            if target is not None:target.focus_set()
        return 'break'

    def _scroll(self,units):
        if self.canvas.yview()!=(0.,1.):self.canvas.yview_scroll(units,'units')
        return 'break'

    def _wheel(self,event):
        if isinstance(event.widget,tk.Listbox):return 'break'
        return self._scroll(-1 if event.delta>0 else 1)

    def _reveal_focus(self,event):
        widget=event.widget
        if not str(widget).startswith(str(self.page)+'.'):return
        self.update_idletasks()
        y=widget.winfo_rooty()-self.sheet.winfo_rooty()
        top=self.canvas.canvasy(0);height=self.canvas.winfo_height()
        if y<top:self.canvas.yview_moveto(y/max(1,self.sheet.winfo_height()))
        elif y+widget.winfo_height()>top+height:
            self.canvas.yview_moveto((y+widget.winfo_height()-height)/max(1,self.sheet.winfo_height()))


# Source: pycommander/vcsactions.py
"""Read-only VCS discovery/status and explicit Tortoise dialog hand-off.

No command in this module stages, commits, fetches or pushes. GUI commands only
open the client's confirmation dialog; authentication remains with that client.
"""

import os
import shutil
import subprocess
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class VcsLocation:
    kind: str
    root: Path


@dataclass(frozen=True)
class VcsContext:
    location: VcsLocation | None
    focus: Path
    paths: tuple[Path, ...]
    reason: str = ""
    mixed: bool = False


@dataclass(frozen=True)
class VcsSummary:
    changed: int = 0
    untracked: int = 0
    conflicts: int = 0
    branch: str = ""
    upstream: str = ""
    ahead: int | None = None
    behind: int | None = None
    url: str = ""
    error: str = ""


def vcs_absolute(path):
    # Do not resolve a tracked symlink into an unrelated repository.
    return Path(os.path.abspath(path))


def vcs_location(path):
    path = vcs_absolute(path)
    if any(part.casefold() in {'.git', '.svn'} for part in path.parts):
        return None
    directory = path if path.is_dir() else path.parent
    for candidate in (directory, *directory.parents):
        for kind, marker in (('git', '.git'), ('svn', '.svn')):
            if (candidate / marker).exists():
                # A .git file represents a worktree/submodule, not its parent's repo.
                return VcsLocation(kind, candidate)
    return None


def vcs_context(paths, focus, virtual=False):
    focus = vcs_absolute(focus)
    paths = tuple(dict.fromkeys(vcs_absolute(p) for p in paths)) or (focus,)
    if virtual:
        return VcsContext(None, focus, paths, 'Archive previews are not working copies.')
    try:
        location = vcs_location(focus)
        if location is None:
            return VcsContext(None, focus, paths, 'Not a Git or SVN working copy.')
        mixed = any(vcs_location(p) != location for p in paths)
        return VcsContext(location, focus, paths, mixed=mixed)
    except OSError:
        return VcsContext(None, focus, paths, 'Working copy is unavailable.')


def vcs_run(command):
    env = os.environ.copy()
    # Local status must never open a terminal/authentication dialog or update the index.
    env.update(GIT_TERMINAL_PROMPT='0', GIT_OPTIONAL_LOCKS='0')
    result = subprocess.run(command, capture_output=True, timeout=4, env=env,
                            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
    if result.returncode:
        raise ValueError('VCS status unavailable')
    return result.stdout


def vcs_cli(kind):
    if os.name == 'nt':
        # Windows executable lookup otherwise searches the current working directory.
        # Merely selecting a repository must not execute its own git.exe/svn.exe.
        found = next((result for entry in os.environ.get('PATH', '').split(os.pathsep)
                      if entry and Path(entry).is_absolute()
                      for result in [shutil.which(str(Path(entry) / (kind + '.exe')))] if result), None)
    else:
        found = shutil.which(kind)
    if found:
        return found
    if os.name == 'nt':
        for variable in ('ProgramFiles', 'ProgramW6432', 'ProgramFiles(x86)', 'LOCALAPPDATA'):
            base = os.environ.get(variable)
            if base:
                relative = ('Programs/Git/cmd/git.exe' if variable=='LOCALAPPDATA' else 'Git/cmd/git.exe') if kind=='git' else 'TortoiseSVN/bin/svn.exe'
                if variable=='LOCALAPPDATA' and kind!='git':continue
                if not Path(base).is_absolute():continue
                candidate = Path(base) / relative
                if candidate.is_file():
                    return str(candidate)
    return None


def vcs_parse_git_status(data):
    values = dict(changed=0, untracked=0, conflicts=0, branch='', upstream='',
                  ahead=None, behind=None)
    records = iter(data.split(b'\0'))
    for record in records:
        if record.startswith(b'# branch.head '):
            values['branch'] = record[14:].decode('utf-8', 'replace')
        elif record.startswith(b'# branch.upstream '):
            values['upstream'] = record[18:].decode('utf-8', 'replace')
        elif record.startswith(b'# branch.ab '):
            counts = record[12:].split()
            values['ahead'], values['behind'] = int(counts[0]), abs(int(counts[1]))
        elif record.startswith(b'? '):
            values['untracked'] += 1
        elif record.startswith(b'u '):
            values['conflicts'] += 1
        elif record.startswith((b'1 ', b'2 ')):
            values['changed'] += 1
            if record.startswith(b'2 '):
                next(records, None)  # second path can contain arbitrary characters
    return VcsSummary(**values)


def vcs_status(context):
    if context.location is None:
        return VcsSummary(error=context.reason)
    if context.mixed:
        return VcsSummary(error='Selection spans working copies. Select items from one working copy.')
    kind, root = context.location.kind, context.location.root
    executable = vcs_cli(kind)
    if executable is None:
        return VcsSummary(error='Command-line client not found. Tortoise dialogs are still available.')
    try:
        if kind == 'git':
            command = [executable, '--no-optional-locks', '--literal-pathspecs', '-c', 'core.fsmonitor=false', '-C', str(root),
                       'status', '--porcelain=v2', '--branch', '-z', '--untracked-files=normal', '--']
            command.extend(os.path.relpath(p, root) for p in context.paths)
            return vcs_parse_git_status(vcs_run(command))
        # status/info without -u are local-only; @ disambiguates literal peg characters.
        targets = [str(p) + '@' for p in context.paths]
        document = ET.fromstring(vcs_run([executable, 'status', '--xml', '--non-interactive',
                                         '--ignore-externals', '--', *targets]))
        changed = untracked = conflicts = 0
        seen = set()
        for entry in document.findall('.//entry'):
            path = entry.get('path')
            if path in seen:
                continue
            seen.add(path)
            wc = entry.find('wc-status')
            if wc is None:
                continue
            item, props = wc.get('item'), wc.get('props')
            if item == 'conflicted' or props == 'conflicted' or wc.get('tree-conflicted') == 'true':
                conflicts += 1
            elif item == 'unversioned':
                untracked += 1
            elif item in {'modified', 'added', 'deleted', 'missing', 'replaced', 'obstructed', 'incomplete'} or props == 'modified':
                changed += 1
        # An untracked item has no info, but its nearest versioned parent does.
        url = ''
        for info_path in dict.fromkeys((context.focus, context.focus.parent, root)):
            if info_path != root and root not in info_path.parents:
                continue
            try:
                info = ET.fromstring(vcs_run([executable, 'info', '--xml', '--non-interactive',
                                             '--', str(info_path) + '@']))
                url = info.findtext('.//relative-url') or info.findtext('.//url') or ''
                break
            except ValueError:
                continue
        return VcsSummary(changed, untracked, conflicts, url=url)
    except (OSError, subprocess.SubprocessError, ValueError, ET.ParseError):
        return VcsSummary(error='Status unavailable or timed out. No changes were made.')


VCS_CLIENT_NAMES = {'git': 'TortoiseGitProc.exe', 'svn': 'TortoiseProc.exe'}


def vcs_find_client(kind, configured=''):
    name = VCS_CLIENT_NAMES[kind]
    candidates = [configured] if configured else []
    if os.name == 'nt':
        # Only known installation locations/explicit preferences, never the working repo.
        try:
            import winreg
            for hive in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):
                for view in (winreg.KEY_WOW64_64KEY, winreg.KEY_WOW64_32KEY):
                    try:
                        product = 'TortoiseGit' if kind == 'git' else 'TortoiseSVN'
                        with winreg.OpenKey(hive, 'Software\\' + product, 0, winreg.KEY_READ | view) as key:
                            candidates.append(str(Path(winreg.QueryValueEx(key, 'Directory')[0]) / 'bin' / name))
                    except OSError:
                        pass
        except ImportError:
            pass
        for variable in ('ProgramFiles', 'ProgramFiles(x86)', 'ProgramW6432'):
            base = os.environ.get(variable)
            if base:
                candidates.append(str(Path(base) / ('TortoiseGit' if kind == 'git' else 'TortoiseSVN') / 'bin' / name))
    for candidate in candidates:
        if candidate and Path(candidate).is_absolute() and Path(candidate).is_file() and Path(candidate).name.casefold() == name.casefold():
            return str(candidate)
    return None


def vcs_dialog_command(executable, context, action):
    if context.location is None:
        raise ValueError('Not a Git or SVN working copy.')
    if action not in {'commit', 'commit_all', 'push', 'log', 'revisiongraph'}:
        raise ValueError('Unsupported VCS action')
    if action in {'commit', 'commit_all', 'push'} and context.mixed:
        raise ValueError('Selection spans working copies. Select items from one working copy.')
    location = context.location
    if action == 'push' and location.kind != 'git':
        raise ValueError('SVN does not use Push')
    if action == 'commit':
        paths = context.paths
    elif action in {'commit_all', 'push'} or (action == 'revisiongraph' and location.kind == 'git'):
        paths = (location.root,)
    else:
        paths = (context.focus,)
    if any('*' in str(p) or '\0' in str(p) for p in paths):
        raise ValueError('Unsupported path characters')
    command = 'commit' if action == 'commit_all' else action
    arguments = [str(executable), '/command:' + command, '/path:' + '*'.join(map(str, paths))]
    if len(subprocess.list2cmdline(arguments).encode('utf-16-le')) > 60000:
        raise ValueError('Too many selected paths. Select fewer items or their parent folder.')
    return arguments


# Source: pycommander/actionbar.py
"""Single-line action bar: measured widths, stable zoom, no font shrinking."""

import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk





class ActionBarLayout:
    def __init__(self, app, frame):
        self.app, self.frame = app, frame
        self.labels = {}
        self.job = None
        self.mode = 'full'
        frame.pack_propagate(False)
        frame.bind('<Configure>', lambda _e: self.schedule(), add='+')
        frame.bind('<Destroy>', self._destroy, add='+')
        for button, key, label in app.action_buttons:
            button.pack_forget()
            self.labels[key] = (str(button.cget('text')), str(button.cget('text')))
            if key != 'F8':
                button._pfc_tooltip = ToolTip(button, lambda k=key: self.help(k), delay=650)
        self.localize()

    def _destroy(self, event):
        if event.widget is self.frame and self.job:
            self.frame.after_cancel(self.job)
            self.job = None

    def localize(self):
        short = {'F2': 'Rename', 'F3': 'Preview', 'F4': 'Search', 'F5': 'Copy',
                 'F6': 'Move', 'F7': 'Folder', 'F9': 'Compare', 'F11': 'Copy Path', 'F12': 'Path'}
        for button, key, label in self.app.action_buttons:
            if key != 'F8':
                self.set_label(key, f'{key} {tr(label)}', f'{key} {tr(short[key])}')

    def help(self, key):
        descriptions = {'F2': 'Rename the selected item.', 'F3': 'Open the selected item in PFC Preview.',
                        'F4': 'Search for files and folders below the current path.',
                        'F7': 'Create a folder here.', 'F9': 'Compare selected files or folders.',
                        'F11': 'Copy all selected full paths as text.',
                        'F12': 'Focus and select the path bar for direct paste.'}
        full = self.labels[key][0]
        return full + ('\n' + tr(descriptions[key]) if key in descriptions else '')

    def set_label(self, key, full, compact=None):
        value = (full, compact or full)
        if self.labels.get(key) != value:
            self.labels[key] = value
            self.app.action_button_by_hotkey[key].configure(text=full)
            self.schedule()

    def schedule(self):
        if self.job is None:
            self.job = self.frame.after_idle(self.layout)

    def layout(self):
        self.job = None
        if not self.frame.winfo_exists():
            return
        font = tkfont.nametofont('TkDefaultFont')
        padding = max(8, round(font.metrics('linespace') * .35))
        ttk.Style(self.app).configure('Action.TButton', padding=(2, 2))
        keys = [key for _, key, _ in self.app.action_buttons]
        available = max(1, self.frame.winfo_width())
        # Reserve the same F8 space for Git, SVN and VCS to avoid selection jitter.
        def widths(labels):
            return [max(font.measure(text), font.measure('F8 VCS') if key == 'F8' else 0) + padding + 2
                    for key, text in zip(keys, labels)]
        labels = [self.labels[key][0] for key in keys]
        self.mode = 'full'
        if sum(widths(labels)) > available:
            labels = [self.labels[key][1] for key in keys]
            self.mode = 'compact'
        if sum(widths(labels)) > available:
            # Reduce individual long labels first; F5/F6 keep their destination.
            self.mode = 'keys'
            for i in sorted(range(len(keys)), key=lambda i: font.measure(labels[i]), reverse=True):
                if keys[i] not in {'F5', 'F6', 'F8'}:
                    labels[i] = keys[i]
                if sum(widths(labels)) <= available:
                    break
        measured = widths(labels)
        total = sum(measured)
        spare = max(0, available - total)
        height = font.metrics('linespace') + padding + 4
        if self.frame.winfo_reqheight() != height:
            self.frame.configure(height=height)
        x = 0
        for i, (button, key, _) in enumerate(self.app.action_buttons):
            width = measured[i] + spare // len(keys) + (1 if i < spare % len(keys) else 0)
            # All supported main-window sizes fit the key-only baseline.
            if button.cget('text') != labels[i]:
                button.configure(text=labels[i])
            button.configure(style='Action.TButton')
            button.place(x=x, y=0, width=max(1, width - 2), height=height)
            x += width


# Source: pycommander/flowlayout.py
"""Measured, task-grouped toolbars without shrinking fonts or equal-width waste."""
from tkinter import ttk


def toolbar_rows(width, sizes, gap=6):
    """Greedily retain adjacent semantic groups; exact fits stay on one row."""
    rows, row, used = [], [], 0
    for index, size in enumerate(sizes):
        size = max(1, int(size))
        if row and used + gap + size > max(1, width):
            rows.append(row); row, used = [], 0
        used += (gap if row else 0) + size
        row.append(index)
    if row: rows.append(row)
    return rows


class FlowToolbar(ttk.Frame):
    """Place whole groups by measured minimum widths; expand only useful inputs.

    Children keep their pack/grid layout internally. Requested geometry is never
    derived from the width just assigned by us (avoids resize feedback loops).
    No polling, file I/O, font reduction, or widget recreation during reflow.
    """
    def __init__(self, master, *, gap=6, row_gap=3, **kwargs):
        super().__init__(master, **kwargs)
        self.gap, self.row_gap = gap, row_gap
        self.groups = []
        self.rows = []
        self._flow_job = None
        self._flow_signature = None
        self.bind('<Configure>', self.schedule, add='+')
        self.bind('<Map>', self.schedule, add='+')
        self.bind('<<ThemeChanged>>', self.schedule, add='+')
        self.bind('<Destroy>', self._flow_destroy, add='+')

    def add(self, widget, *, expand=False, minimum=None):
        self.groups.append((widget, expand, minimum))
        widget.bind('<Configure>', self.schedule, add='+')
        self.schedule()

    def schedule(self, _event=None):
        if self._flow_job is None:
            self._flow_job = self.after_idle(self.layout)

    def _flow_destroy(self, event):
        if event.widget is self and self._flow_job is not None:
            self.after_cancel(self._flow_job)
            self._flow_job = None

    def layout(self):
        self._flow_job = None
        width = max(1, self.winfo_width())
        sizes = [max(1, int(minimum() if callable(minimum) else minimum or w.winfo_reqwidth()))
                 for w, _, minimum in self.groups]
        heights = [w.winfo_reqheight() for w, _, _ in self.groups]
        signature = (width, tuple(sizes), tuple(heights))
        if signature == self._flow_signature: return
        self._flow_signature = signature
        self.rows = toolbar_rows(width, sizes, self.gap)
        y = 0
        for row in self.rows:
            height = max(heights[i] for i in row)
            spare = max(0, width-sum(sizes[i] for i in row)-self.gap*(len(row)-1))
            growing = [i for i in row if self.groups[i][1]]
            x = 0
            for i in row:
                extra = (spare//len(growing)+(i == growing[-1])*(spare % len(growing))) if i in growing else 0
                allocated = min(width, sizes[i]+extra)
                self.groups[i][0].place(x=x, y=y, width=allocated, height=height)
                x += allocated+self.gap
            y += height+self.row_gap
        self.configure(height=max(1, y-self.row_gap))


# Source: pycommander/vcsui.py
"""F8 and context menus share one asynchronous, selection-scoped VCS controller."""

import os
import queue
import subprocess
import threading
import time
import tkinter as tk
import tkinter.font as tkfont
from pathlib import Path
from tkinter import filedialog, messagebox







class VcsActions:
    def __init__(self, app):
        self.app = app
        self.context = None
        self.key = None
        self.tree_target = False
        self.pending = None
        self.busy = False
        self.stopped = False
        self.results = queue.Queue()
        self.status_cache = {}
        self.clients = {}
        self.debounce = None
        self.poll_job = app.after(80, self._poll)
        self.menus = []
        self.processes = []
        self.tooltip = tr('Not a Git or SVN working copy.')
        button = app.action_button_by_hotkey['F8']
        button._pfc_tooltip = ToolTip(button, lambda: self.tooltip, delay=650)
        tree = app.folder_tree.tree
        tree.bind('<FocusIn>', lambda _e: self.request(tree=True), add='+')
        tree.bind('<<TreeviewSelect>>', lambda _e: self.request(), add='+')
        app.bind('<FocusIn>', self._focus, add='+')
        app.bind('<Destroy>', self._destroy, add='+')
        self.request()

    def _focus(self, event):
        if any(event.widget is pane.tree for pane in self.app.all_panes()):
            self.request(tree=False)
        elif event.widget is self.app.folder_tree.tree:
            self.request(tree=True)

    def _destroy(self, event):
        if event.widget is self.app:
            self.stopped = True
            for job in (self.debounce, self.poll_job):
                if job:
                    try: self.app.after_cancel(job)
                    except tk.TclError: pass

    def snapshot(self, pane=None, clicked=None, tree_path=None):
        pane = pane or self.app.active
        if tree_path is not None:
            return ((tree_path,), tree_path, False)
        if self.tree_target and self.app._single_layout and clicked is None:
            tree = self.app.folder_tree
            selection = tree.tree.selection()
            iid = tree.tree.focus()
            if iid not in selection:
                iid = selection[0] if selection else ''
            path = tree.paths.get(iid)
            if path is None:
                return ((), Path(os.path.abspath(os.sep)), True)
            return ((path,), path, False)
        paths = tuple(pane.selected_paths())
        iid = pane.tree.focus()
        tags = pane.tree.item(iid, 'tags') if iid and pane.tree.exists(iid) else ()
        focus = clicked or (Path(tags[0]) if tags and Path(tags[0]) in paths else None)
        focus = focus or (paths[0] if paths else pane.path)
        return (paths or (focus,), focus, pane.archive_session is not None)

    def request(self, tree=None):
        if self.stopped:
            return
        if tree is not None:
            self.tree_target = tree
        snapshot = self.snapshot()
        if snapshot != self.key:
            self.key = snapshot
            self.context = None
            self.tooltip = tr('Checking working copy…')
            self._button(None)
        if self.debounce:
            self.app.after_cancel(self.debounce)
        self.debounce = self.app.after(200, lambda: self._discover(snapshot))

    def _discover(self, snapshot):
        self.debounce = None
        if snapshot != self.key or self.context is not None:
            return
        self._queue(('context', snapshot))

    def _queue(self, task):
        # One worker and one latest request: rapid navigation cannot create a thread storm.
        if self.busy:
            if task[0] == 'context' or self.pending is None or self.pending[0] != 'context':
                self.pending = task
            return
        self.busy = True
        def work():
            try:
                value = vcs_context(*task[1]) if task[0] == 'context' else vcs_status(task[1])
                clients = {}
                if task[0] == 'context' and value.location:
                    kind = value.location.kind
                    clients[kind] = vcs_find_client(kind, self.app_vcs_paths.get(kind, ''))
                self.results.put((task, value, clients))
            except Exception:
                # Never leave the controller permanently busy after filesystem races.
                self.results.put((task, None, {}))
        # Copy Tk/config state on the GUI thread; workers never call Tk.
        self.app_vcs_paths = {kind: self.app.config_data.get('vcs', kind + '_client', fallback='')
                              for kind in ('git', 'svn')}
        threading.Thread(target=work, daemon=True, name='PFC-VCS-actions').start()

    def _poll(self):
        self.poll_job = None
        if self.stopped:
            return
        try:
            task, value, clients = self.results.get_nowait()
            self.busy = False
            self.clients.update(clients)
            if task[0] == 'context' and task[1] == self.key:
                self.context = value
                self.tooltip = (tr(value.reason) if value and not value.location else
                                tr('Version Control') + (' — ' + str(value.focus) if value else ''))
                self._button(value)
                for menu, snapshot, context in list(self.menus):
                    if snapshot == self.key and context is None:
                        self._populate(menu, snapshot, value)
            elif task[0] == 'status' and value is not None:
                self.status_cache[task[1]] = (time.monotonic(), value)
                if len(self.status_cache) > 64:
                    self.status_cache.pop(next(iter(self.status_cache)))
                for menu, snapshot, context in list(self.menus):
                    if context == task[1]:
                        self._summary(menu, context, value)
            pending, self.pending = self.pending, None
            if pending:
                self._queue(pending)
        except queue.Empty:
            pass
        finished = [p for p in self.processes if p.poll() is not None]
        if finished:
            self.processes = [p for p in self.processes if p not in finished]
            self.invalidate()
        self.menus = [(m, s, c) for m, s, c in self.menus if m.winfo_exists()]
        self.poll_job = self.app.after(80, self._poll)

    def _button(self, context):
        button = self.app.action_button_by_hotkey['F8']
        kind = context.location.kind if context and context.location else None
        label = {'git': 'Git', 'svn': 'SVN'}.get(kind, 'VCS')
        self.app.action_bar.set_label('F8', 'F8 ' + label, 'F8 ' + label)
        button.state(['!disabled'] if kind else ['disabled'])

    def invalidate(self):
        self.status_cache.clear()
        invalidate_vcs_cache()
        self.context = None
        self.request()
        # Refresh only existing VCS badges, never rebuild rows or move selection.
        for pane in self.app.all_panes():
            pane._vcs_generation += 1
            pane._vcs_loading = False
            pane._vcs_requested_at = 0
            pane._request_vcs_statuses()

    def _clip(self, text):
        limit = min(650, max(240, self.app.winfo_screenwidth() - 120))
        font = tkfont.nametofont('TkMenuFont')
        text = str(text).replace('\n', ' ').replace('\r', ' ').replace('\t', ' ')
        if font.measure(text) <= limit:
            return text
        left, right = len(text) // 2, len(text) // 2
        while left > 1 and font.measure(text[:left] + '…' + text[-right:]) > limit:
            left -= 1; right = max(1, right - 1)
        return text[:left] + '…' + text[-right:]

    def build_menu(self, parent, pane=None, clicked=None, tree_path=None):
        snapshot = self.snapshot(pane, clicked, tree_path)
        context = self.context if snapshot == self.key else None
        menu = tk.Menu(parent, tearoff=False, font='TkMenuFont')
        self.menus.append((menu, snapshot, context))
        self._populate(menu, snapshot, context)
        if context is None:
            self.key = snapshot
            self.context = None
            self._queue(('context', snapshot))
        return menu

    def _populate(self, menu, snapshot, context):
        if not menu.winfo_exists():
            return
        self.menus = [(m, s, context if m is menu else c) for m, s, c in self.menus]
        menu.delete(0, 'end')
        menu._vcs_headers = {}
        if not context or not context.location:
            menu.add_command(label=tr(context.reason if context else 'Checking working copy…'), state='disabled')
            self._redraw(menu)
            return
        kind = context.location.kind
        for key in ('location', 'scope', 'changes', 'remote'):
            menu._vcs_headers[key] = menu.index('end') + 1 if menu.index('end') is not None else 0
            menu.add_command(label=tr('Checking status…'), state='disabled')
        menu.add_separator()
        for action, label in [('commit', 'Commit selected…'), ('commit_all', 'Commit entire working copy…'),
                              ('push', 'Push current branch…'), ('log', 'Show History'),
                              ('revisiongraph', 'Show Graph')]:
            if action == 'push' and kind == 'svn':
                continue
            if kind == 'svn' and action in {'log', 'revisiongraph'}:
                label = label + ' (may use network)'
            state = 'disabled' if context.mixed and action in {'commit', 'commit_all', 'push'} else 'normal'
            menu.add_command(label=tr(label), state=state,
                             command=lambda a=action, c=context: self.launch(c, a))
        menu.add_separator()
        menu.add_command(label=tr('Refresh status'), command=lambda: self.refresh_menu(menu, snapshot, context))
        menu.add_command(label=tr('Choose Tortoise client…'), command=lambda: self.choose_client(kind))
        menu._pfc_tooltip = MenuToolTip(menu, {})
        cached = self.status_cache.get(context)
        self._summary(menu, context, cached[1] if cached else None)
        if not cached or time.monotonic() - cached[0] > 3:
            self._queue(('status', context))

    def _summary(self, menu, context, summary):
        if not menu.winfo_exists() or not getattr(menu, '_vcs_headers', None):
            return
        kind = 'Git' if context.location.kind == 'git' else 'SVN'
        branch = summary.branch if summary else ''
        if branch == '(detached)':
            branch = 'detached HEAD'
        location = kind + ' · ' + (branch or (summary.url if summary else '') or context.location.root.name)
        scope = tr('Selected: {count} · {path}', count=len(context.paths), path=context.focus)
        changes = tr('Checking status…')
        if summary:
            changes = (tr(summary.error) if summary.error else
                       tr('Changes {changed} · Untracked {untracked} · Conflicts {conflicts}',
                          changed=summary.changed, untracked=summary.untracked, conflicts=summary.conflicts))
        if context.location.kind == 'svn':
            remote = tr('Commit sends changes to the SVN server; no Push.')
        elif summary and summary.upstream and summary.ahead is not None:
            remote = tr('Push {ahead} · Behind {behind} · {upstream} (cached)', ahead=summary.ahead,
                        behind=summary.behind, upstream=summary.upstream)
        else:
            remote = tr('Push: unknown — no upstream information (no Fetch).')
        if context.mixed:
            changes = tr('Selection spans working copies. Select items from one working copy.')
        for key, full in zip(('location', 'scope', 'changes', 'remote'), (location, scope, changes, remote)):
            label = self._clip(full)
            menu.entryconfigure(menu._vcs_headers[key], label=label)
            menu._pfc_tooltip.descriptions[label] = full
            self.app.header_popup.descriptions[label] = full
        self._redraw(menu)

    def _redraw(self, menu):
        for popup in list(self.app.header_popup.popups):
            if popup.menu is menu:
                popup.refresh()
                if getattr(menu, '_vcs_above_button', False):
                    button = self.app.action_button_by_hotkey['F8']
                    popup.show(button.winfo_rootx(), button.winfo_rooty() - popup.height - 4)

    def refresh_menu(self, menu, snapshot, context):
        self.status_cache.pop(context, None)
        self._queue(('status', context))
        # Menu commands close the popup first; reopen the same scoped menu.
        self.app.after_idle(lambda: self._show(menu))

    def _show(self, menu):
        if not menu.winfo_exists():
            return
        button = self.app.action_button_by_hotkey['F8']
        menu._vcs_above_button = True
        self.app.header_popup.show_at(button.winfo_rootx(), button.winfo_rooty(), menu)
        popup = self.app.header_popup.popups[0]
        popup.show(button.winfo_rootx(), button.winfo_rooty() - popup.height - 4)

    def show(self):
        # Compare/preview/search own their keys. Never act on the hidden main selection.
        focused = self.app.focus_get()
        if self.app._settings_are_open() or self.app.grab_current() or (
                focused is not None and focused.winfo_toplevel() is not self.app):
            return 'break'
        old = getattr(self, 'quick_menu', None)
        self.app.header_popup.close_all()
        if old is not None:
            old.destroy()
        self.quick_menu = self.build_menu(self.app)
        self._show(self.quick_menu)
        return 'break'

    def choose_client(self, kind):
        if os.name != 'nt':
            messagebox.showinfo(tr('Version Control'), tr('Tortoise integration requires Windows.'), parent=self.app)
            return None
        filename = filedialog.askopenfilename(parent=self.app, title=tr('Choose Tortoise client…'),
                    filetypes=[(VCS_CLIENT_NAMES[kind], VCS_CLIENT_NAMES[kind])])
        if not filename:
            return None
        executable = vcs_find_client(kind, filename)
        if not executable or os.path.normcase(executable) != os.path.normcase(filename):
            messagebox.showerror(tr('Version Control'), tr('Select the matching Tortoise executable.'), parent=self.app)
            return None
        if not self.app.config_data.has_section('vcs'):
            self.app.config_data.add_section('vcs')
        self.app.config_data.set('vcs', kind + '_client', executable)
        self.app.save_config()
        self.clients[kind] = executable
        return executable

    def launch(self, context, action):
        if os.name != 'nt':
            messagebox.showinfo(tr('Version Control'), tr('Tortoise integration requires Windows.'), parent=self.app)
            return
        kind = context.location.kind
        executable = self.clients.get(kind)
        if not executable:
            messagebox.showinfo(tr('Version Control'),
                tr('Tortoise client not found. Choose an installed client; nothing will be installed.'), parent=self.app)
            executable = self.choose_client(kind)
        if not executable:
            return
        try:
            command = vcs_dialog_command(executable, context, action)
            self.processes.append(subprocess.Popen(command, cwd=context.location.root,
                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0)))
        except (OSError, ValueError) as exc:
            messagebox.showerror(tr('Version Control'), tr(str(exc)), parent=self.app)


# Source: pycommander/comparecolors.py
"""Shared comparison semantics, independent of application accent colors."""


def comparison_colors(palette):
    color=palette.get('content','#ffffff').lstrip('#')
    dark=len(color)==6 and sum(int(color[n:n+2],16) for n in (0,2,4))<384
    if dark:
        return dict(base='#23282e',text='#f1f3f5',line='#513238',inline='#81454c',
                    orphan='#403452',gap='#30363e',gutter='#2b323a',muted='#bcc5cf',
                    match='#66561b',match_text='#fff2b0',current='#284d70',current_text='#ffffff')
    return dict(base='#ffffff',text='#202830',line='#fde9e7',inline='#f4b8b2',
                orphan='#eee6f7',gap='#edf0f3',gutter='#f2f4f6',muted='#56616d',
                match='#fff0a6',match_text='#292600',current='#d5e8fa',current_text='#153955')


def style_comparison_text(widget,palette):
    colors=comparison_colors(palette)
    widget.configure(background=colors['base'],foreground=colors['text'],insertbackground=colors['text'],
                     selectbackground='#245e91',selectforeground='#ffffff')
    for tag,key in [('diff','line'),('inline_diff','inline'),('orphan','orphan'),('gap','gap')]:
        widget.tag_configure(tag,background=colors[key],foreground=colors['text'])
    # Current difference is a navigation cue, not selection of every character.
    widget.tag_configure('current',background='',foreground='',underline=True)
    widget.tag_configure('match',background=colors['match'],foreground=colors['match_text'])
    widget.tag_configure('current_match',background=colors['match'],foreground=colors['match_text'],underline=True)
    for tag in ('diff','orphan','gap','inline_diff','current','match','current_match','sel'):widget.tag_raise(tag)
    return colors


# Source: pycommander/reviewcore.py
"""Comparison data, independent of Tk. No automatic writes to source files."""
from array import array
from bisect import bisect_right, bisect_left
from collections import Counter
import difflib
import hashlib
import json
from pathlib import Path


REVIEW_LIMIT = 20 * 1024 * 1024


class LineIndex:
    """Compact line offsets; unlike splitlines(), a million rows aren't objects."""
    def __init__(self, text):
        self.text = text
        self.starts = array('I', [0])
        start = 0
        while True:
            start = text.find('\n', start)
            if start < 0: break
            start += 1
            self.starts.append(start)

    def __len__(self):
        return len(self.starts)

    def __getitem__(self, key):
        if isinstance(key, slice):
            return [self[i] for i in range(*key.indices(len(self))) ]
        if key < 0: key += len(self)
        if not 0 <= key < len(self): raise IndexError(key)
        end = self.starts[key + 1] - 1 if key + 1 < len(self) else len(self.text)
        return self.text[self.starts[key]:end]

    def span(self, start, stop):
        a = self.starts[start] if start < len(self) else len(self.text)
        b = self.starts[stop] if stop < len(self) else len(self.text)
        return a, b


def review_opcodes(left, right):
    """Patience anchors plus bounded fine alignment; coarse changes stay honest.

    No positional fallback: an insertion never makes the remaining file differ.
    Oversized ambiguous spans are a replace block, not an equality assertion.
    """
    a, b = LineIndex(left), LineIndex(right)
    if left == right:
        return [('equal', 0, len(a), 0, len(b))]
    # Digest keys bound memory for wide lines. Equality is checked against source
    # text before anchors are used, rather than trusting hash equality alone.
    def keys(lines):
        return [hashlib.blake2b(lines.text[slice(*lines.span(i,i+1))].encode('utf-8'), digest_size=16).digest()
                for i in range(len(lines))]
    ka, kb = keys(a), keys(b)
    ca, cb = Counter(ka), Counter(kb)
    positions = {key: i for i, key in enumerate(kb) if cb[key] == 1}
    pairs = [(i, positions[key]) for i, key in enumerate(ka)
             if ca[key] == 1 and key in positions and a[i] == b[positions[key]]]
    tails, tail_indices, previous = [], [], []
    for index, (_, j) in enumerate(pairs):
        k = bisect_left(tails, j)
        previous.append(tail_indices[k-1] if k else -1)
        if k == len(tails): tails.append(j); tail_indices.append(index)
        else: tails[k] = j; tail_indices[k] = index
    anchors = []
    node = tail_indices[-1] if tail_indices else -1
    while node >= 0:
        anchors.append(pairs[node]); node = previous[node]
    anchors.reverse()
    result = []
    def emit(tag, i, x, j, y):
        if i == x and j == y: return
        if result and result[-1][0] == tag and result[-1][2] == i and result[-1][4] == j:
            old = result.pop(); result.append((tag, old[1], x, old[3], y))
        else: result.append((tag, i, x, j, y))
    def gap(i, x, j, y):
        while i < x and j < y and ka[i] == kb[j] and a[i] == b[j]:
            emit('equal', i, i+1, j, j+1); i += 1; j += 1
        end_x, end_y = x, y
        while i < x and j < y and ka[x-1] == kb[y-1] and a[x-1] == b[y-1]: x -= 1; y -= 1
        if i == x: emit('insert', i, x, j, y)
        elif j == y: emit('delete', i, x, j, y)
        elif (x-i)*(y-j) <= 1_000_000 and max(x-i, y-j) <= 4000:
            ta=[a.text[slice(*a.span(n,n+1))] for n in range(i,x)]
            tb=[b.text[slice(*b.span(n,n+1))] for n in range(j,y)]
            for tag, p, q, r, s in difflib.SequenceMatcher(None, ta, tb, autojunk=False).get_opcodes():
                emit(tag, i+p, i+q, j+r, j+s)
        else: emit('replace', i, x, j, y)
        emit('equal', x, end_x, y, end_y)
    i = j = 0
    for x, y in anchors:
        gap(i, x, j, y); emit('equal', x, x+1, y, y+1); i, j = x+1, y+1
    gap(i, len(a), j, len(b))
    return result


class ReviewAlignment:
    def __init__(self, left, right, opcodes):
        self.lines = (LineIndex(left), LineIndex(right))
        self.opcodes = opcodes
        self.starts = [0]
        self.differences = []
        for n, (tag, a, b, c, d) in enumerate(opcodes):
            if tag != 'equal': self.differences.append(n)
            self.starts.append(self.starts[-1] + max(b-a, d-c))

    def row(self, number):
        block = min(len(self.opcodes)-1, bisect_right(self.starts, number)-1)
        tag, a, b, c, d = self.opcodes[block]
        offset = number-self.starts[block]
        return block, (a+offset if a+offset < b else None), (c+offset if c+offset < d else None)

    def block_key(self, index):
        tag, a, b, c, d = self.opcodes[index]
        return hashlib.sha256(json.dumps([tag, a, b, c, d,
            self.lines[0].text[slice(*self.lines[0].span(a,b))],
            self.lines[1].text[slice(*self.lines[1].span(c,d))]], ensure_ascii=False).encode()).hexdigest()

    def take(self, index, source):
        tag, a, b, c, d = self.opcodes[index]
        spans = (self.lines[0].span(a,b), self.lines[1].span(c,d))
        target = 1-source; lo, hi = spans[target]
        chunk = self.lines[source].text[slice(*spans[source])]
        return self.lines[target].text[:lo] + chunk + self.lines[target].text[hi:]


def review_state(texts, checked):
    return {'format': 'pfc-review-1',
            'digests': [hashlib.sha256(t.encode()).hexdigest() for t in texts],
            'checked': sorted(checked)}


def restore_review_state(record, texts):
    expected = review_state(texts, ())
    if record.get('format') != expected['format'] or record.get('digests') != expected['digests']:
        raise ValueError('Review belongs to different document contents; no marks restored.')
    checked = record.get('checked')
    if not isinstance(checked, list) or len(checked) > 1_000_000 or any(
            not isinstance(k, str) or len(k) != 64 for k in checked):
        raise ValueError('Invalid review marks')
    return set(checked)


