        self.title(tr("PFC Search")); self.geometry(config.get("search", "geometry", fallback="1100x720")); self.minsize(720, 480)
        self.protocol("WM_DELETE_WINDOW", self.close); self.bind("<Escape>", lambda _e: (self.escape(),'break')[1])
